window.NEURO = {"decks": [{"id": "emb", "title": "Embryology"}, {"id": "path", "title": "Visual Pathway"}, {"id": "reflex", "title": "Visual and Ocular Reflexes"}], "questions": [{"id": "Q001", "deck": "emb", "ref": "slide-emb-3", "page": 3, "topic": "Neurulation", "stem": "Which embryonic structure induces overlying ectoderm to form the neural plate during week 3?", "options": [{"text": "Neural crest", "why": "Neural crest arises at the plate border; it is a product of neural development rather than the initiating axial organizer."}, {"text": "Surface ectoderm alone", "why": "Surface ectoderm requires regional inductive signals to acquire neural fate."}, {"text": "Third pharyngeal pouch", "why": "This endodermal pouch produces thymic and inferior parathyroid tissue, not the neural plate organizer."}, {"text": "Somitic dermatome", "why": "Dermatome makes dermis and is not the midline inducer of neural plate formation."}, {"text": "Notochord", "why": "The axial mesodermal notochord provides inductive signals to overlying ectoderm, initiating neural plate development."}], "answer": 4}, {"id": "Q002", "deck": "emb", "ref": "slide-emb-3", "page": 3, "topic": "Neurulation", "stem": "A week-3 embryo has a thickened neural plate but no closed tube. Which sequence normally follows?", "options": [{"text": "Neural tube, neural plate, neural groove", "why": "This reverses the normal morphologic sequence."}, {"text": "Neural canal obliteration, epidermal fusion, neural plate", "why": "The canal is retained as the ventricular system and central canal, not normally obliterated."}, {"text": "Neural groove and folds, fusion, separation from surface ectoderm", "why": "Plate bending creates a groove bounded by folds; fusion produces the tube and separates it from the future epidermis."}, {"text": "Neural crest fusion, neural plate formation, neural groove", "why": "The plate precedes groove formation; neural folds, rather than migrating crest cells, fuse."}, {"text": "Pharyngeal pouch fusion, neural groove, neural tube", "why": "Pouches do not generate the neural tube."}], "answer": 2}, {"id": "Q003", "deck": "emb", "ref": "slide-emb-3", "page": 3, "topic": "Neurulation", "stem": "In an experimental embryo, floor-plate and ventral motor-neuron differentiation are impaired after loss of an axial signaling molecule. Which pathway is most directly implicated?", "options": [{"text": "Sonic hedgehog signaling", "why": "SHH from notochord and floor plate patterns ventral neural tissue; the deck also names BMP/TGF-beta and Wnt pathways as participants in neurulation."}, {"text": "Retinal phototransduction", "why": "Light signaling is unrelated to induction of ventral embryonic neural identities."}, {"text": "Calcitonin signaling", "why": "Calcitonin regulates calcium homeostasis and is not the axial ventralizing signal."}, {"text": "Thyroid hormone release from a mature follicle", "why": "A mature thyroid is not required to establish the early ventral neural tube."}, {"text": "Acetylcholine at the neuromuscular junction", "why": "This mediates mature muscle activation rather than early neural patterning."}], "answer": 0}, {"id": "Q004", "deck": "emb", "ref": "slide-emb-3", "page": 3, "topic": "Neurulation", "stem": "Which pairing best describes dorsal versus ventral neural-tube patterning?", "options": [{"text": "Endoderm dorsally; epidermis ventrally", "why": "These tissues are not the correctly located signaling centers for this relationship."}, {"text": "Folate dorsally; calcitonin ventrally", "why": "Folate supports development but is not the paired positional morphogen in this scheme."}, {"text": "SHH dorsally; BMP exclusively ventrally", "why": "This reverses the classic dorsal-ventral signaling relationship."}, {"text": "CN III dorsally; CN VII ventrally", "why": "Cranial nerves are differentiated structures, not early positional morphogens."}, {"text": "BMP/TGF-beta signals dorsally; SHH signals ventrally", "why": "Roof-plate/overlying ectoderm BMP signaling favors dorsal identities, whereas notochord/floor-plate SHH favors ventral identities. Wnt pathways also participate in plate shaping and regional patterning."}], "answer": 4}, {"id": "Q005", "deck": "emb", "ref": "slide-emb-3", "page": 3, "topic": "Neurulation", "stem": "Which neural-tube plate forms motor regions of the spinal cord?", "options": [{"text": "Neural crest alone", "why": "Crest forms peripheral ganglia and glia, not the spinal motor-neuron pool."}, {"text": "Third pouch", "why": "This forms thymic/inferior parathyroid tissue."}, {"text": "Surface ectoderm", "why": "This forms epidermal and other surface derivatives rather than spinal motor gray matter."}, {"text": "Alar plate", "why": "The alar plate is associated with dorsal sensory regions."}, {"text": "Basal plate", "why": "Ventral basal plate develops motor regions, while dorsal alar plate contributes sensory processing regions; this is a high-yield extension of SHH/BMP patterning."}], "answer": 4}, {"id": "Q006", "deck": "emb", "ref": "slide-emb-4", "page": 4, "topic": "Neurulation", "stem": "Where does neural-fold fusion first begin in the standard human embryology teaching model?", "options": [{"text": "Future cervical region", "why": "Closure begins near the future cervical region and progresses toward the cranial and caudal ends."}, {"text": "Rostral neuropore only", "why": "The rostral end closes after fusion has begun more centrally."}, {"text": "Caudal neuropore only", "why": "The caudal neuropore closes later, rather than initiating closure."}, {"text": "Optic cup", "why": "The optic cup is a forebrain outgrowth, not the initial fusion site."}, {"text": "Foramen cecum", "why": "This marks thyroid descent on the tongue and has no role in neural-fold fusion."}], "answer": 0}, {"id": "Q007", "deck": "emb", "ref": "slide-emb-4", "page": 4, "topic": "Neurulation", "stem": "Which approximate closure times are correct for the rostral and caudal neuropores, respectively?", "options": [{"text": "Day 25 and day 27", "why": "These are the deck's approximate embryonic ages; closure is normally completed by the end of week 4."}, {"text": "Week 7 and week 10", "why": "These dates are too late for primary neural tube closure."}, {"text": "Day 40 and day 42", "why": "Primary closure occurs considerably earlier in development."}, {"text": "Day 27 and day 25", "why": "This reverses the usual cranial-before-caudal sequence."}, {"text": "Day 17 and day 19", "why": "Day 17 corresponds approximately to neural plate formation, before normal neuropore closure."}], "answer": 0}, {"id": "Q008", "deck": "emb", "ref": "slide-emb-4", "page": 4, "topic": "Neurulation", "stem": "The lumen of the neural tube becomes which adult structures?", "options": [{"text": "Dural venous sinuses", "why": "These are vascular channels within dura, not neural canal derivatives."}, {"text": "Peripheral nerve fascicles", "why": "Peripheral nerves do not arise as transformed neural tube lumina."}, {"text": "Brain ventricles and spinal central canal", "why": "The neural canal persists as the CSF-containing ventricular system and central canal; the tube wall becomes CNS tissue."}, {"text": "External acoustic meatus", "why": "This is a first pharyngeal cleft derivative."}, {"text": "Subarachnoid space alone", "why": "The subarachnoid space forms around the CNS, not from the neural tube lumen."}], "answer": 2}, {"id": "Q009", "deck": "emb", "ref": "slide-emb-5", "page": 5, "topic": "Brain vesicles", "stem": "A congenital lesion selectively impairs telencephalic development. Which structures are most directly affected?", "options": [{"text": "Cerebral hemispheres and lateral ventricles", "why": "The telencephalon is a secondary forebrain vesicle and produces the hemispheres surrounding the lateral ventricles."}, {"text": "Pons and fourth ventricle", "why": "Pons derives from metencephalon, not telencephalon."}, {"text": "Thalamus and third ventricle", "why": "These are diencephalic derivatives."}, {"text": "Midbrain and cerebral aqueduct", "why": "These are mesencephalic derivatives."}, {"text": "Medulla and caudal fourth ventricle", "why": "These are myelencephalic derivatives."}], "answer": 0}, {"id": "Q010", "deck": "emb", "ref": "slide-emb-5", "page": 5, "topic": "Brain vesicles", "stem": "The retina, hypothalamus, thalamus, epithalamus, and subthalamus share which secondary brain-vesicle origin?", "options": [{"text": "Metencephalon", "why": "This forms pons and cerebellum."}, {"text": "Mesencephalon", "why": "This forms the midbrain around the cerebral aqueduct."}, {"text": "Myelencephalon", "why": "This forms the medulla."}, {"text": "Telencephalon", "why": "This forms the cerebral hemispheres and lateral ventricles."}, {"text": "Diencephalon", "why": "The diencephalon surrounds the third ventricle and gives rise to these forebrain structures, including the neural retina."}], "answer": 4}, {"id": "Q011", "deck": "emb", "ref": "slide-emb-5", "page": 5, "topic": "Brain vesicles", "stem": "Congenital aqueductal stenosis obstructs a cavity derived from which primary brain vesicle?", "options": [{"text": "Prosencephalon", "why": "Forebrain cavities become lateral and third ventricles, not the aqueduct."}, {"text": "Telencephalon", "why": "This is a secondary, not primary, vesicle and surrounds lateral ventricles."}, {"text": "Rhombencephalon", "why": "Hindbrain cavities contribute to the fourth ventricle and caudal canal."}, {"text": "Mesencephalon", "why": "The mesencephalon remains the midbrain, and its narrow cavity becomes the cerebral aqueduct."}, {"text": "Metencephalon", "why": "This secondary hindbrain vesicle contributes to the fourth ventricle."}], "answer": 3}, {"id": "Q012", "deck": "emb", "ref": "slide-emb-5", "page": 5, "topic": "Brain vesicles", "stem": "Which secondary vesicle forms the pons and cerebellum?", "options": [{"text": "Telencephalon", "why": "This produces cerebral hemispheres."}, {"text": "Myelencephalon", "why": "The caudal hindbrain vesicle produces the medulla."}, {"text": "Metencephalon", "why": "The rostral secondary hindbrain vesicle forms pons and cerebellum and contributes to the fourth ventricular cavity."}, {"text": "Diencephalon", "why": "This produces thalamic/hypothalamic structures and retina."}, {"text": "Mesencephalon", "why": "This produces midbrain, not pons and cerebellum."}], "answer": 2}, {"id": "Q013", "deck": "emb", "ref": "slide-emb-5", "page": 5, "topic": "Brain vesicles", "stem": "The embryonic myelencephalon gives rise to which mature region?", "options": [{"text": "Cerebral cortex", "why": "Cortex develops from telencephalon."}, {"text": "Cerebellum", "why": "Cerebellum develops from metencephalon."}, {"text": "Midbrain tectum", "why": "The tectum is mesencephalic."}, {"text": "Medulla oblongata", "why": "Myelencephalon is the caudal secondary hindbrain vesicle; its cavity contributes to the fourth ventricle and transition to the central canal."}, {"text": "Retina", "why": "Retina develops from diencephalic neuroectoderm."}], "answer": 3}, {"id": "Q014", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "A cell at the neural plate border loses epithelial attachments and acquires the ability to migrate through embryonic tissues. What process is illustrated?", "options": [{"text": "Epithelial-to-mesenchymal transition of neural crest", "why": "EMT permits crest cells to delaminate and migrate into peripheral and craniofacial sites. Timing varies by region; cranial migration can begin before complete tube closure."}, {"text": "Formation of CSF by choroid plexus", "why": "CSF secretion is not the cellular transition described."}, {"text": "Ventricular canal degeneration", "why": "The canal normally persists, and its fate is unrelated to crest EMT."}, {"text": "Differentiation of crest into surface ectoderm without migration", "why": "The defining event described is acquisition of migratory mesenchymal behavior."}, {"text": "Closure of a pharyngeal cleft", "why": "Cleft obliteration does not describe neural plate border delamination."}], "answer": 0}, {"id": "Q015", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "Which group consists entirely of neural crest derivatives?", "options": [{"text": "Adrenal cortex, renal tubules, and gonads", "why": "These structures are mesodermal."}, {"text": "Dorsal root ganglia, Schwann cells, and adrenal medulla", "why": "Sensory ganglia, peripheral glia, and chromaffin cells are classic neural crest derivatives shown in the source diagram."}, {"text": "Oligodendrocytes, retina, and cerebral cortex", "why": "These are neural tube neuroectoderm derivatives rather than neural crest."}, {"text": "Lens, enamel, and epidermis", "why": "These are surface ectoderm derivatives."}, {"text": "Thyroid follicles, liver, and pancreatic epithelium", "why": "These epithelial structures are endodermal."}], "answer": 1}, {"id": "Q016", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "A newborn has distal colonic aganglionosis and severe constipation. Failure of which migrating population best explains this high-yield neural crest disorder?", "options": [{"text": "Surface ectodermal melanoblast precursors", "why": "Melanocytes are crest-derived, but surface ectoderm does not produce the enteric neuronal population."}, {"text": "Pharyngeal pouch endoderm", "why": "Pouches form head/neck epithelial derivatives rather than enteric neurons."}, {"text": "Enteric neural crest precursors", "why": "Crest cells normally form enteric ganglia; failure to populate distal bowel causes Hirschsprung disease, a related application of the diagram's enteric nervous system derivative."}, {"text": "Intermediate mesoderm", "why": "This forms much of the urogenital system."}, {"text": "Neural tube motor neurons", "why": "These form CNS motor neurons rather than the enteric plexuses."}], "answer": 2}, {"id": "Q017", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "Which pair has a neural crest origin?", "options": [{"text": "Retinal photoreceptors and pinealocytes", "why": "These derive from neural tube neuroectoderm."}, {"text": "Hepatocytes and pancreatic acinar cells", "why": "These epithelial cells derive from endoderm."}, {"text": "Adrenal cortical cells and splenic stromal cells", "why": "These are mesodermal derivatives."}, {"text": "Melanocytes and odontoblasts", "why": "Pigment cells and dentin-producing odontoblasts are crest derivatives; enamel-producing ameloblasts instead arise from oral ectoderm."}, {"text": "Keratinocytes and ameloblasts", "why": "These derive from surface/oral ectoderm, not neural crest."}], "answer": 3}, {"id": "Q018", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "An embryology diagram groups the retina, pineal body, posterior pituitary, and CNS together. Which origin unites them?", "options": [{"text": "Neural tube neuroectoderm", "why": "These structures develop from neural tube neuroectoderm, with retina and posterior pituitary associated with forebrain outgrowths."}, {"text": "Surface ectoderm", "why": "Lens and anterior pituitary, rather than retina and posterior pituitary, are surface ectodermal."}, {"text": "Intermediate mesoderm", "why": "This produces urogenital structures."}, {"text": "Pharyngeal endoderm", "why": "This produces pouch and thyroid epithelial derivatives."}, {"text": "Neural crest", "why": "Crest produces peripheral ganglia/glia and many craniofacial tissues rather than this entire group."}], "answer": 0}, {"id": "Q019", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "Which set is correctly assigned to surface ectoderm in the source's germ-layer diagram?", "options": [{"text": "Schwann cells, melanocytes, and adrenal medulla", "why": "These are neural crest derivatives."}, {"text": "Lens, corneal epithelium, anterior pituitary, enamel, and inner ear", "why": "Lens/corneal epithelium and epidermal appendages derive from surface ectoderm; oral and otic ectoderm produce adenohypophysis/enamel and inner ear, respectively."}, {"text": "Gonads, kidneys, and adrenal cortex", "why": "These arise from mesodermal lineages."}, {"text": "Thyroid follicles, tonsillar epithelium, and auditory tube", "why": "These are endodermal derivatives."}, {"text": "Retina, optic nerve, and posterior pituitary", "why": "These are neural neuroectodermal derivatives."}], "answer": 1}, {"id": "Q020", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "Which epithelial group is endodermal in origin?", "options": [{"text": "Peripheral ganglia, odontoblasts, and Schwann cells", "why": "These are neural crest derivatives."}, {"text": "Respiratory/GI lining, liver, pancreas, thyroid follicles, and parathyroids", "why": "The source chart lists these endodermal epithelia, together with middle-ear/auditory-tube/tonsillar epithelia and much of bladder/urachal lining. Surrounding connective tissues can have other origins."}, {"text": "Heart muscle, blood cells, and spleen", "why": "These are mesodermal derivatives."}, {"text": "CNS, retina, and pineal gland", "why": "These are neural tube derivatives."}, {"text": "Epidermis, mammary glands, and nails", "why": "These are surface ectodermal derivatives."}], "answer": 1}, {"id": "Q021", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "The diagram separates paraxial, intermediate, and lateral mesoderm. Which assignment is correct?", "options": [{"text": "Intermediate mesoderm forms kidneys and much of the genital system", "why": "Intermediate mesoderm supplies urogenital organs, ducts, and associated structures."}, {"text": "Paraxial mesoderm forms the adrenal medulla", "why": "Adrenal medulla comes from neural crest."}, {"text": "Paraxial mesoderm forms thyroid follicular epithelium", "why": "Thyroid follicular epithelium comes from endoderm."}, {"text": "Intermediate mesoderm forms the neural retina", "why": "Retina develops from diencephalic neuroectoderm."}, {"text": "Lateral mesoderm forms epidermal appendages", "why": "These arise from surface ectoderm."}], "answer": 0}, {"id": "Q022", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "Which pairing correctly distinguishes the other mesodermal categories in the source diagram?", "options": [{"text": "Paraxial mesoderm: anterior pituitary; lateral plate: enamel", "why": "Both are derived from surface/oral ectoderm."}, {"text": "Paraxial mesoderm: lens; lateral plate: retina", "why": "Both assigned structures instead arise from ectodermal lineages."}, {"text": "Paraxial mesoderm: much skeletal muscle/dermis; lateral plate mesoderm: visceral muscle, serosa, cardiovascular tissues", "why": "These are the diagram's broad derivative groups. Blood/lymph lineages, spleen, and adrenal cortex are mesodermal; cranial connective tissue also has substantial neural crest contributions."}, {"text": "Paraxial mesoderm: thyroid follicles; lateral plate: pancreatic epithelium", "why": "Both epithelia are endodermal."}, {"text": "Paraxial mesoderm: enteric neurons; lateral plate: melanocytes", "why": "Both are neural crest derivatives."}], "answer": 2}, {"id": "Q023", "deck": "emb", "ref": "slide-emb-6", "page": 6, "topic": "Neural crest and germ layers", "stem": "The germ-layer illustration includes 'dentin' in a mesoderm box while also listing neural crest odontoblasts. Which statement is the best clarification for studying human tooth development?", "options": [{"text": "Dentin and enamel are both neural tube derivatives", "why": "Neither dental tissue is a neural tube product."}, {"text": "Dentin is produced by adrenal cortical cells", "why": "These cells have no role in tooth dentin production."}, {"text": "All dental tissues are foregut endoderm", "why": "Tooth development uses epithelial/mesenchymal interactions with ectodermal/crest contributions."}, {"text": "Dentin is produced by neural crest-derived odontoblasts; enamel by oral ectoderm-derived ameloblasts", "why": "Cranial ectomesenchyme is crest-derived, so the diagram's broad 'head mesoderm/dentin' grouping should not override the specific odontoblast lineage."}, {"text": "Dentin is made by ameloblasts and enamel by odontoblasts", "why": "This reverses the two producing cells."}], "answer": 3}, {"id": "Q024", "deck": "emb", "ref": "slide-emb-7", "page": 7, "topic": "Neural tube defects", "stem": "Prenatal ultrasound shows absence of most cerebral tissue and the cranial vault. Failure of which process is most likely?", "options": [{"text": "Caudal neuropore closure alone", "why": "This is associated with spinal neural tube defects rather than anencephaly."}, {"text": "Fusion of maxillary and medial nasal prominences", "why": "This produces cleft lip."}, {"text": "Division of the forebrain after tube closure", "why": "This produces holoprosencephaly, not the classic absent-vault closure defect."}, {"text": "Rostral neuropore closure", "why": "Anencephaly follows failure of cranial neural tube closure and involves severe loss of cerebral hemispheres and calvarium."}, {"text": "Migration of inferior parathyroids", "why": "This does not explain absent brain and cranial vault."}], "answer": 3}, {"id": "Q025", "deck": "emb", "ref": "slide-emb-7", "page": 7, "topic": "Neural tube defects", "stem": "An infant has an open lumbosacral neural lesion. Which embryologic failure best fits this lesion category?", "options": [{"text": "Prosencephalic division", "why": "Failure causes holoprosencephaly."}, {"text": "Caudal neural tube closure", "why": "Failure of posterior closure is associated with open spinal dysraphism. A simple closed vertebral arch defect is distinguished from exposed neural tissue."}, {"text": "Intermaxillary segment formation", "why": "Failure affects facial midline/primary palate development."}, {"text": "Rostral neuropore closure", "why": "Failure here classically causes anencephaly."}, {"text": "Obliteration of the second pharyngeal cleft", "why": "Failure produces a lateral neck cyst or tract."}], "answer": 1}, {"id": "Q026", "deck": "emb", "ref": "slide-emb-8", "page": 8, "topic": "Neural tube defects", "stem": "An asymptomatic adolescent has a small lumbosacral hair tuft. Imaging shows failure of posterior vertebral arch fusion, with intact cord and meninges and no herniating sac. What is the diagnosis?", "options": [{"text": "Holoprosencephaly", "why": "This concerns forebrain separation, not a vertebral arch defect."}, {"text": "Myelomeningocele", "why": "Myelomeningocele includes neural tissue within the sac and commonly causes deficits."}, {"text": "Spina bifida occulta", "why": "A bony posterior arch defect without meningeal/neural herniation is the defining finding; some cutaneous markers warrant evaluation for occult dysraphism."}, {"text": "Anencephaly", "why": "This is a cranial closure defect."}, {"text": "Meningocele", "why": "Meningocele includes a meningeal/CSF-filled herniating sac."}], "answer": 2}, {"id": "Q027", "deck": "emb", "ref": "slide-emb-8", "page": 8, "topic": "Neural tube defects", "stem": "A newborn has a CSF-filled sac protruding through a vertebral defect. Imaging finds meninges in the sac but no spinal cord tissue. Motor function is preserved. Which diagnosis is most likely?", "options": [{"text": "Spina bifida occulta", "why": "Occulta has no protruding meningeal sac."}, {"text": "Meningocele", "why": "The sac contains meninges and CSF without spinal cord; neurologic deficits are often absent but depend on associated abnormalities."}, {"text": "Myelomeningocele", "why": "This contains cord/neural tissue within the protrusion."}, {"text": "Thyroglossal duct cyst", "why": "This is a neck remnant of thyroid descent, not spinal meningeal herniation."}, {"text": "Lissencephaly", "why": "This is a cortical migration disorder."}], "answer": 1}, {"id": "Q028", "deck": "emb", "ref": "slide-emb-8", "page": 8, "topic": "Neural tube defects", "stem": "A lumbosacral sac in a neonate contains meninges and neural tissue. Examination reveals weak legs, sensory loss, and urinary dysfunction. Which additional concern follows most directly from exposed neural tissue?", "options": [{"text": "Isolated ossicular fixation", "why": "This is unrelated to exposed spinal neural tissue."}, {"text": "Infection of the exposed neural structures", "why": "Myelomeningocele contains neural tissue and may cause motor, sensory, and bowel/bladder deficits; exposed tissue increases infection risk."}, {"text": "Lens accommodation failure alone", "why": "This concerns ocular parasympathetic pathways."}, {"text": "T-cell deficiency from thymic aplasia", "why": "This suggests pharyngeal pouch dysfunction, not the mechanism here."}, {"text": "Failure of nasal retinal fibers to cross", "why": "This would affect visual pathways rather than the spinal lesion."}], "answer": 1}, {"id": "Q029", "deck": "emb", "ref": "slide-emb-8", "page": 8, "topic": "Neural tube defects", "stem": "A newborn with lumbosacral myelomeningocele develops hydrocephalus and imaging shows downward displacement of posterior fossa structures. Which associated malformation is most classic?", "options": [{"text": "Isolated Chiari I as the obligatory association", "why": "Chiari I mainly involves tonsillar ectopia and is not the classic myelomeningocele association."}, {"text": "Adie tonic pupil", "why": "This is an ocular parasympathetic disorder."}, {"text": "Chiari II malformation", "why": "Myelomeningocele is strongly associated with Chiari II and hydrocephalus; this is a related NBME association beyond sac-content classification."}, {"text": "Branchial cleft cyst", "why": "This is a lateral neck remnant rather than a posterior fossa malformation."}, {"text": "Treacher Collins syndrome", "why": "This is mandibulofacial dysostosis, not the characteristic posterior fossa association."}], "answer": 2}, {"id": "Q030", "deck": "emb", "ref": "slide-emb-9", "page": 9, "topic": "Neural tube defects", "stem": "The source photographs show a cervical meningocele and a myelomeningocele. Which finding is the most useful distinction between these lesions?", "options": [{"text": "Presence of spinal neural tissue within the sac", "why": "A meningocele contains meninges/CSF, whereas a myelomeningocele contains neural tissue; location or external appearance alone cannot reliably establish contents."}, {"text": "A skin hair tuft proves an open myelomeningocele", "why": "Hair tufts can mark closed occult dysraphism and are not proof of an open sac."}, {"text": "All myelomeningoceles are closed bony defects", "why": "They include a neural-containing protrusion and may be exposed."}, {"text": "Cervical location always means cord is present", "why": "Meningoceles can occur cervically; region does not determine sac contents."}, {"text": "All meningoceles produce profound leg paralysis", "why": "Deficits are often absent in uncomplicated meningoceles."}], "answer": 0}, {"id": "Q031", "deck": "emb", "ref": "slide-emb-10", "page": 10, "topic": "NTD prevention and screening", "stem": "A patient plans pregnancy and asks when folate is most relevant to neural tube defect prevention. Which answer best matches the embryology?", "options": [{"text": "Only during the third trimester", "why": "This is too late to cover primary neurulation."}, {"text": "Before conception and during early pregnancy", "why": "Closure occurs during the first month after fertilization, often before pregnancy recognition, so adequate folate must be present early."}, {"text": "Only after an infant's birth", "why": "Postnatal supplementation cannot prevent an already formed closure defect."}, {"text": "Only during labor", "why": "Labor occurs far after the developmental event."}, {"text": "Only after week 20", "why": "Neural tube closure has long been completed by this time."}], "answer": 1}, {"id": "Q032", "deck": "emb", "ref": "slide-emb-10", "page": 10, "topic": "NTD prevention and screening", "stem": "Which antiseizure medication in a pregnant patient's history is a classic neural tube defect risk factor?", "options": [{"text": "Penicillin V", "why": "This antibiotic is not the classic antiseizure teratogen described."}, {"text": "Valproic acid", "why": "The deck specifically identifies valproate and carbamazepine as associated with increased NTD risk; medication planning requires individualized clinical review."}, {"text": "Folic acid", "why": "Folate supplementation reduces risk rather than increasing it."}, {"text": "Acetaminophen", "why": "This analgesic is not the antiseizure medication association tested here."}, {"text": "Levothyroxine", "why": "This thyroid replacement is not the named antiseizure risk factor."}], "answer": 1}, {"id": "Q033", "deck": "emb", "ref": "slide-emb-10", "page": 10, "topic": "NTD prevention and screening", "stem": "A student claims neural tube defects are determined only by nutrition. Which observation in the deck argues against that conclusion?", "options": [{"text": "Caudal closure normally occurs after birth", "why": "Closure is prenatal and normally completed by day 28."}, {"text": "Higher concordance in monozygotic twins supports genetic susceptibility", "why": "NTDs are multifactorial: folate, medications such as carbamazepine/valproate, and genetic susceptibility all matter."}, {"text": "All cases are caused by a pharyngeal pouch deletion", "why": "Pharyngeal pouch disorders are a different developmental category."}, {"text": "Folate deficiency is protective", "why": "Folate deficiency increases risk."}, {"text": "Only one gene causes every neural tube defect", "why": "The source does not support universal monogenic inheritance."}], "answer": 1}, {"id": "Q034", "deck": "emb", "ref": "slide-emb-10", "page": 10, "topic": "NTD prevention and screening", "stem": "Maternal serum screening shows elevated alpha-fetoprotein. Ultrasound identifies an open spinal defect. Which additional amniotic-fluid finding supports an open neural tube defect?", "options": [{"text": "Elevated acetylcholinesterase", "why": "Open neural tissue can produce elevated amniotic AFP and acetylcholinesterase; AFP is a screening clue rather than a standalone diagnosis."}, {"text": "High CSF oligoclonal bands in maternal serum", "why": "These do not diagnose fetal neural tube closure defects."}, {"text": "Low bilirubin as a specific marker", "why": "This is not the characteristic NTD marker."}, {"text": "Low AFP as the defining finding", "why": "Open NTDs classically elevate AFP; closed occulta may not elevate it."}, {"text": "Absent calcitonin", "why": "Calcitonin is unrelated to detecting exposed fetal neural tissue."}], "answer": 0}, {"id": "Q035", "deck": "emb", "ref": "slide-emb-10", "page": 10, "topic": "NTD prevention and screening", "stem": "For an average-risk person who could become pregnant, which daily folic acid amount is the general CDC recommendation to reduce neural tube defect risk?", "options": [{"text": "40 milligrams", "why": "This is far above the average-risk recommendation."}, {"text": "400 micrograms", "why": "CDC recommends 400 micrograms daily; previous NTD pregnancy requires clinician-directed higher-dose planning rather than automatically using the average-risk amount."}, {"text": "No folic acid before pregnancy recognition", "why": "Neural closure occurs early, so preconception intake matters."}, {"text": "40 micrograms", "why": "This is below the general recommendation."}, {"text": "4 micrograms", "why": "This is far below the general recommendation."}], "answer": 1}, {"id": "Q036", "deck": "emb", "ref": "slide-emb-11", "page": 11, "topic": "Forebrain developmental disorders", "stem": "A newborn has severe midline facial abnormalities and imaging shows failure of separation of the cerebral hemispheres. Which mechanism best explains the findings?", "options": [{"text": "Abnormal neuronal migration alone", "why": "This is the classic basis of lissencephaly."}, {"text": "Failure of rostral neuropore closure", "why": "That causes anencephaly rather than a formed but unseparated forebrain."}, {"text": "Failure of caudal neuropore closure", "why": "This causes spinal dysraphism."}, {"text": "Failure of prosencephalon division", "why": "Holoprosencephaly is defective forebrain cleavage, with severe forms producing cyclopia and other midline facial defects."}, {"text": "Persistent thyroglossal duct", "why": "This causes a midline neck remnant, not forebrain nonseparation."}], "answer": 3}, {"id": "Q037", "deck": "emb", "ref": "slide-emb-11", "page": 11, "topic": "Forebrain developmental disorders", "stem": "Holoprosencephaly is classically associated with which combination?", "options": [{"text": "Valproate exposure and stapes fixation as the defining pair", "why": "Valproate is an NTD risk; stapes fixation is an ossicular problem."}, {"text": "TCOF1 mutation and trisomy 18 as the defining pair", "why": "TCOF1 is associated with Treacher Collins syndrome."}, {"text": "DCX mutation and trisomy 21 as the defining pair", "why": "DCX is associated with neuronal migration disorders; this is not the deck's classic pair."}, {"text": "22q11.2 deletion and isolated thymic hyperplasia", "why": "DiGeorge features involve thymic/parathyroid hypoplasia, not this classic forebrain association."}, {"text": "SHH pathway abnormalities and trisomy 13", "why": "SHH is important in midline patterning, and trisomy 13 is a classic chromosomal association of holoprosencephaly."}], "answer": 4}, {"id": "Q038", "deck": "emb", "ref": "slide-emb-11", "page": 11, "topic": "Forebrain developmental disorders", "stem": "Which feature distinguishes anencephaly from holoprosencephaly?", "options": [{"text": "Holoprosencephaly is always isolated vertebral arch nonfusion", "why": "That describes neither forebrain nonseparation nor its facial associations."}, {"text": "Anencephaly is failure of palatal shelf fusion", "why": "This defines cleft palate."}, {"text": "Both disorders result from posterior pharyngeal cleft persistence", "why": "Cleft persistence produces neck anomalies, not these CNS malformations."}, {"text": "Anencephaly is usually a harmless incidental finding", "why": "Anencephaly is severe and typically lethal."}, {"text": "Anencephaly involves cranial closure failure with loss of much of the hemispheres and calvarium", "why": "Holoprosencephaly instead reflects failure of forebrain division; both can be severe, but the developmental mechanisms differ."}], "answer": 4}, {"id": "Q039", "deck": "emb", "ref": "slide-emb-12", "page": 12, "topic": "Neuronal migration and growth", "stem": "An infant has seizures, severe developmental delay, and a smooth cerebral surface with markedly reduced gyri. Which developmental process is primarily abnormal?", "options": [{"text": "Neuronal migration", "why": "Lissencephaly is a cortical migration disorder; LIS1/PAFAH1B1 and DCX are classic associated genes."}, {"text": "Lens flattening during distance vision", "why": "This is normal mature accommodation physiology."}, {"text": "Formation of the external acoustic meatus", "why": "This is a first-cleft process."}, {"text": "Obliteration of the cervical sinus", "why": "This relates to lateral neck cysts."}, {"text": "Posterior vertebral arch ossification only", "why": "This would not explain the smooth cerebral cortex."}], "answer": 0}, {"id": "Q040", "deck": "emb", "ref": "slide-emb-12", "page": 12, "topic": "Neuronal migration and growth", "stem": "Which gene pair is most associated with classic lissencephaly in these slides?", "options": [{"text": "RET and APC", "why": "These are not the deck's classic lissencephaly gene pair."}, {"text": "PAFAH1B1 (LIS1) and DCX", "why": "Both participate in neuronal migration; variants can produce abnormal cortical gyration and neurodevelopmental impairment."}, {"text": "HBB and F8", "why": "These are hematologic disease genes."}, {"text": "TCOF1 and TBX1", "why": "These are associated with craniofacial and pharyngeal developmental syndromes, respectively."}, {"text": "CFTR and DMD", "why": "These cause cystic fibrosis and dystrophinopathies rather than classic lissencephaly."}], "answer": 1}, {"id": "Q041", "deck": "emb", "ref": "slide-emb-12", "page": 12, "topic": "Neuronal migration and growth", "stem": "A fetus exposed to congenital Zika infection develops markedly reduced head circumference. Which term and mechanism best fit?", "options": [{"text": "Meningocele due to tonsillar epithelial failure", "why": "This is not a mechanism of a small head."}, {"text": "Lissencephaly defined solely by head circumference", "why": "Lissencephaly is defined by abnormal cortical gyration, not head size alone."}, {"text": "Microcephaly due to impaired brain growth", "why": "Microcephaly is an abnormally small head associated with impaired brain growth; genetic disorders and congenital infections are relevant causes."}, {"text": "Anencephaly caused by second-cleft persistence", "why": "Anencephaly is a rostral neural tube closure defect."}, {"text": "Holoprosencephaly caused by delayed thyroid descent", "why": "Holoprosencephaly concerns forebrain division, not thyroid migration."}], "answer": 2}, {"id": "Q042", "deck": "emb", "ref": "slide-emb-14", "page": 14, "topic": "Pharyngeal architecture", "stem": "Cranial neural crest cells enter the pharyngeal arches. Which tissue contribution is most characteristic?", "options": [{"text": "All circulating blood cells", "why": "Blood cells are mesodermal derivatives rather than a characteristic cranial crest product."}, {"text": "All arch skeletal muscle fibers", "why": "Arch muscle derives mainly from mesoderm, despite important crest patterning interactions."}, {"text": "External epidermal lining of clefts", "why": "Cleft epithelium is ectodermal."}, {"text": "Craniofacial skeletal and connective tissues", "why": "Crest contributes extensively to arch cartilage, bone, connective tissue, and vascular smooth muscle; arch skeletal muscle is principally mesodermal."}, {"text": "Internal epithelial lining of every pouch", "why": "Pouch epithelium is endodermal."}], "answer": 3}, {"id": "Q043", "deck": "emb", "ref": "slide-emb-15", "page": 15, "topic": "Pharyngeal architecture", "stem": "The arches, pouches, and clefts mainly organize head and neck development during which interval in the deck?", "options": [{"text": "Only after birth", "why": "These are embryonic structures."}, {"text": "Only during implantation", "why": "Implantation precedes the relevant organogenesis."}, {"text": "Weeks 4–7", "why": "The pharyngeal apparatus becomes apparent early in week 4 and develops through this interval."}, {"text": "Weeks 20–24 only", "why": "This is much later than initial arch and pouch development."}, {"text": "Days 1–3", "why": "This is before formation of the embryonic head and pharyngeal apparatus."}], "answer": 2}, {"id": "Q044", "deck": "emb", "ref": "slide-emb-16", "page": 16, "topic": "Arch derivatives", "stem": "Which pharyngeal arch supplies the malleus, incus, and mandibular skeletal region?", "options": [{"text": "Fourth arch", "why": "Fourth contributes to laryngeal/pharyngeal structures, not malleus and incus."}, {"text": "Sixth arch", "why": "Sixth is associated with intrinsic laryngeal structures and recurrent laryngeal innervation."}, {"text": "First arch", "why": "The mandibular arch contributes these structures. Much of the mandible ossifies in crest-derived mesenchyme adjacent to Meckel cartilage rather than simply replacing that cartilage."}, {"text": "Third arch", "why": "Third arch contributes greater horn/lower body of hyoid."}, {"text": "Second arch", "why": "Second arch contributes stapes, styloid process, and lesser hyoid components."}], "answer": 2}, {"id": "Q045", "deck": "emb", "ref": "slide-emb-16", "page": 16, "topic": "Arch derivatives", "stem": "A developmental lesion affects muscles of mastication, mylohyoid, and anterior belly of digastric. Which nerve supplies this arch muscle group?", "options": [{"text": "CN IX", "why": "IX supplies third-arch stylopharyngeus."}, {"text": "CN VII", "why": "VII supplies second-arch muscles such as facial expression and posterior digastric."}, {"text": "CN XII", "why": "This supplies most tongue muscles and is not the first-arch motor nerve."}, {"text": "Recurrent laryngeal branch of CN X", "why": "This supplies sixth-arch intrinsic laryngeal muscles."}, {"text": "Mandibular division of CN V", "why": "V3 provides branchial motor supply to first-arch muscles, including these muscles and the tensor muscles."}], "answer": 4}, {"id": "Q046", "deck": "emb", "ref": "slide-emb-16", "page": 16, "topic": "Arch derivatives", "stem": "Which two tensor muscles share first-arch origin and V3 innervation?", "options": [{"text": "Tensor tympani and tensor veli palatini", "why": "Both are first-arch muscles; tensor veli palatini is the important exception to most palate muscles being supplied by vagus."}, {"text": "Cricothyroid and posterior cricoarytenoid", "why": "These are vagal laryngeal muscles rather than first-arch tensors."}, {"text": "Stylopharyngeus and stylohyoid", "why": "These belong to third/IX and second/VII arches, respectively."}, {"text": "Stapedius and levator veli palatini", "why": "Stapedius is second arch/VII; levator is vagal rather than V3."}, {"text": "Posterior digastric and stapedius", "why": "Both are second-arch/VII muscles."}], "answer": 0}, {"id": "Q047", "deck": "emb", "ref": "slide-emb-17", "page": 17, "topic": "Arch derivatives", "stem": "A congenital stapes abnormality causes conductive hearing loss. Which arch also produces the styloid process and lesser horn of the hyoid?", "options": [{"text": "First arch", "why": "First gives malleus and incus, not the listed second-arch combination."}, {"text": "Second arch", "why": "Reichert cartilage of the second arch contributes this group; stapes fixation can impair sound transmission."}, {"text": "Third arch", "why": "Third gives the greater horn and lower hyoid body."}, {"text": "Fourth arch", "why": "Fourth contributes laryngeal structures."}, {"text": "Sixth arch", "why": "Sixth contributes laryngeal structures, not this ossicle/styloid group."}], "answer": 1}, {"id": "Q048", "deck": "emb", "ref": "slide-emb-17", "page": 17, "topic": "Arch derivatives", "stem": "Which muscle group is derived from the second arch?", "options": [{"text": "Facial expression muscles, stapedius, stylohyoid, and posterior digastric", "why": "These are all supplied by CN VII, the second-arch nerve."}, {"text": "Intrinsic laryngeal muscles except cricothyroid", "why": "These are chiefly sixth-arch muscles supplied by recurrent laryngeal nerve."}, {"text": "Stylopharyngeus alone", "why": "This is third arch and CN IX."}, {"text": "Genioglossus and hyoglossus", "why": "Most tongue muscles come from occipital somites and receive CN XII."}, {"text": "Mastication muscles and anterior digastric", "why": "These are first-arch/V3 muscles."}], "answer": 0}, {"id": "Q049", "deck": "emb", "ref": "slide-emb-17", "page": 17, "topic": "Arch derivatives", "stem": "A patient cannot tightly close the right eye, smile on the right, or dampen loud sounds through stapedius contraction. The affected motor nerve is associated with which embryonic arch?", "options": [{"text": "Second arch", "why": "CN VII innervates facial expression, orbicularis oculi, and stapedius; these are second-arch muscles."}, {"text": "Third arch", "why": "IX supplies stylopharyngeus."}, {"text": "Fourth arch", "why": "Vagal branches supply pharyngeal muscles and cricothyroid."}, {"text": "First arch", "why": "V3 supplies mastication and tensor tympani, not orbicularis oculi."}, {"text": "Sixth arch", "why": "Recurrent laryngeal nerve supplies most intrinsic laryngeal muscles."}], "answer": 0}, {"id": "Q050", "deck": "emb", "ref": "slide-emb-17", "page": 17, "topic": "Arch derivatives", "stem": "The skeletal diagram labels a ligament between the styloid process and hyoid. Which arch contributes this stylohyoid ligament?", "options": [{"text": "Fourth arch", "why": "This contributes laryngeal/pharyngeal structures."}, {"text": "Third arch", "why": "Third arch gives greater horn and lower hyoid body."}, {"text": "Second arch", "why": "Reichert cartilage derivatives include stapes, styloid process, stylohyoid ligament, and upper/lesser-horn hyoid components."}, {"text": "Sixth arch", "why": "This contributes laryngeal structures rather than the stylohyoid ligament."}, {"text": "First arch", "why": "Meckel cartilage is associated with malleus/incus and first-arch skeletal elements."}], "answer": 2}, {"id": "Q051", "deck": "emb", "ref": "slide-emb-18", "page": 18, "topic": "Arch derivatives", "stem": "Which triad belongs to the third pharyngeal arch?", "options": [{"text": "Laryngeal framework, cricothyroid, superior laryngeal nerve", "why": "This corresponds to fourth-arch associations."}, {"text": "Intrinsic laryngeal muscles, recurrent laryngeal nerve, stapes", "why": "The stapes is second arch and does not belong with sixth-arch laryngeal derivatives."}, {"text": "Mandible, mylohyoid, V3", "why": "This is first arch."}, {"text": "Greater hyoid horn, stylopharyngeus, CN IX", "why": "The third arch forms this skeletal/muscle group; glossopharyngeal nerve also supplies gag afference."}, {"text": "Lesser hyoid horn, stylohyoid, CN VII", "why": "This is second arch."}], "answer": 3}, {"id": "Q052", "deck": "emb", "ref": "slide-emb-18", "page": 18, "topic": "Arch derivatives", "stem": "Touching the posterior pharynx on one side fails to trigger gagging, but the pharyngeal muscles contract when the opposite side is touched. Which nerve's sensory function is most likely impaired?", "options": [{"text": "CN V3", "why": "V3 supplies first-arch muscles and mandibular sensation rather than classic gag afference."}, {"text": "CN VII", "why": "VII is the second-arch motor nerve, not classic gag afference."}, {"text": "CN XII", "why": "XII controls most tongue muscles."}, {"text": "CN IX", "why": "Glossopharyngeal provides the classic gag afferent limb; its arch muscle is stylopharyngeus. This sensory role is distinct from vagal gag motor output."}, {"text": "CN III", "why": "III controls ocular movement and parasympathetic eye responses."}], "answer": 3}, {"id": "Q053", "deck": "emb", "ref": "slide-emb-18", "page": 18, "topic": "Arch derivatives", "stem": "Which arches contribute to the hyoid bone in the illustrated derivative map?", "options": [{"text": "First and sixth only", "why": "This does not match the classic hyoid partition."}, {"text": "Only fifth", "why": "The fifth regresses and has no standard adult derivative set."}, {"text": "Only the neural tube", "why": "The hyoid is not a neural tube skeletal derivative."}, {"text": "Second and third", "why": "Second contributes lesser horn/upper body, while third contributes greater horn/lower body."}, {"text": "Only fourth", "why": "The fourth is associated with laryngeal structures."}], "answer": 3}, {"id": "Q054", "deck": "emb", "ref": "slide-emb-19", "page": 19, "topic": "Arch derivatives", "stem": "A surgical injury weakens cricothyroid and impairs production of high-pitched sounds. Which arch and nerve branch match?", "options": [{"text": "Second arch; CN VII", "why": "VII supplies facial expression and stapedius."}, {"text": "Third arch; CN IX", "why": "IX supplies stylopharyngeus."}, {"text": "First arch; V3", "why": "V3 supplies mastication and tensor muscles."}, {"text": "Sixth arch; recurrent laryngeal nerve", "why": "This matches most intrinsic laryngeal muscles except cricothyroid."}, {"text": "Fourth arch; external branch of superior laryngeal nerve", "why": "Cricothyroid is a fourth-arch muscle innervated by this vagal branch; most other intrinsic laryngeal muscles use recurrent laryngeal nerve."}], "answer": 4}, {"id": "Q055", "deck": "emb", "ref": "slide-emb-19", "page": 19, "topic": "Arch derivatives", "stem": "Postoperative hoarseness follows injury to the recurrent laryngeal nerve. The affected intrinsic laryngeal muscles are chiefly derived from which arch?", "options": [{"text": "Third arch", "why": "Third-arch stylopharyngeus receives IX."}, {"text": "Second arch", "why": "Second-arch muscles receive VII."}, {"text": "Sixth arch", "why": "Sixth-arch muscles receive recurrent laryngeal innervation; cricothyroid is the fourth-arch exception."}, {"text": "First arch", "why": "First-arch muscles receive V3."}, {"text": "Fifth arch", "why": "The fifth arch is rudimentary/regresses and has no standard adult derivative set."}], "answer": 2}, {"id": "Q056", "deck": "emb", "ref": "slide-emb-19", "page": 19, "topic": "Arch derivatives", "stem": "Which statement correctly qualifies the deck's grouping of pharyngeal and palate muscles with arches 4 and 6?", "options": [{"text": "All pharyngeal muscles use VII", "why": "VII is primarily associated with second-arch muscles."}, {"text": "Stylopharyngeus is supplied by recurrent laryngeal nerve", "why": "Stylopharyngeus is supplied by IX."}, {"text": "Most receive CN X, but stylopharyngeus uses IX and tensor veli palatini uses V3", "why": "These exceptions are common exam discriminators when interpreting broad vagal pharyngeal/palatal associations."}, {"text": "All palate muscles use V3", "why": "Only tensor veli palatini uses V3; most palate muscles use X."}, {"text": "Cricothyroid is supplied by CN XII", "why": "It uses the external superior laryngeal branch of X."}], "answer": 2}, {"id": "Q057", "deck": "emb", "ref": "slide-emb-19", "page": 19, "topic": "Arch derivatives", "stem": "Which skeletal group is associated with arches 4 and 6 in the diagram?", "options": [{"text": "Enamel of teeth", "why": "This is oral ectodermal, not laryngeal arch cartilage."}, {"text": "Stapes and styloid process", "why": "These are second-arch derivatives."}, {"text": "Malleus and incus", "why": "These are first-arch derivatives."}, {"text": "Greater horn of hyoid alone", "why": "This is third arch."}, {"text": "Laryngeal cartilages, including thyroid and cricoid framework", "why": "These arches contribute laryngeal skeletal elements; cartilage contributions can be complex, so the grouped framework is the useful relationship."}], "answer": 4}, {"id": "Q058", "deck": "emb", "ref": "slide-emb-20", "page": 20, "topic": "Craniofacial skeleton", "stem": "Which pair best contrasts cranial neural crest and paraxial mesoderm contributions to the skull?", "options": [{"text": "All cranial bones come from surface ectoderm", "why": "Surface ectoderm is not the direct source of the entire skull skeleton."}, {"text": "Neural crest forms only muscles and no skeletal tissues", "why": "Crest is a major craniofacial skeletal lineage; arch muscle is chiefly mesodermal."}, {"text": "Frontal bone comes from endoderm and mandible from neural tube", "why": "Both assignments are incorrect."}, {"text": "Much facial skeleton/frontal bone from crest; parietal and occipital regions from mesoderm", "why": "The diagram contrasts broad anterior crest and posterior mesodermal territories. Its label 'occipital somites' for all red areas is simplified; parietal bone is broadly paraxial mesodermal rather than entirely occipital-somite derived."}, {"text": "All skull bones arise from endoderm", "why": "Endoderm forms epithelial tissues rather than the skull skeleton."}], "answer": 3}, {"id": "Q059", "deck": "emb", "ref": "slide-emb-20", "page": 20, "topic": "Craniofacial skeleton", "stem": "Which set lies in the neural crest-associated facial territory illustrated by the slide?", "options": [{"text": "Lens, enamel, and epidermis", "why": "These are surface ectoderm derivatives rather than the pictured facial bone set."}, {"text": "Retina, pineal gland, and posterior pituitary", "why": "These are neural tube derivatives rather than the facial skeleton."}, {"text": "Kidney, gonad, and adrenal cortex", "why": "These are mesodermal organs, not craniofacial crest skeleton."}, {"text": "Nasal, lacrimal, zygomatic, maxillary, and mandibular bones", "why": "These facial bones are in the illustrated crest-derived region, along with much of the anterior skull and hyoid-related skeleton."}, {"text": "Parietal bone and all posterior cranial base as exclusively crest", "why": "Posterior skull territories have important mesodermal contributions."}], "answer": 3}, {"id": "Q060", "deck": "emb", "ref": "slide-emb-21", "page": 21, "topic": "First-arch disorders", "stem": "A fetus has an absent lower jaw as part of a severe first-arch malformation. Which term describes this finding?", "options": [{"text": "Glossoptosis", "why": "This denotes posterior tongue displacement, not absent jaw."}, {"text": "Meningocele", "why": "This denotes herniation of meninges and CSF."}, {"text": "Microcephaly", "why": "This denotes a small head from impaired brain growth."}, {"text": "Agnathia", "why": "Agnathia denotes absent mandible/extreme first-arch hypoplasia and can be incompatible with life; deficient crest contribution is the mechanism emphasized by the deck."}, {"text": "Lissencephaly", "why": "This denotes abnormally smooth cerebral cortex."}], "answer": 3}, {"id": "Q061", "deck": "emb", "ref": "slide-emb-22", "page": 22, "topic": "First-arch disorders", "stem": "A child has mandibular and zygomatic hypoplasia, downward-slanting palpebral fissures, malformed external ears, and conductive hearing loss. Which diagnosis is most likely?", "options": [{"text": "Holoprosencephaly", "why": "This involves defective forebrain separation and midline facial abnormalities."}, {"text": "Pierre Robin sequence", "why": "Micrognathia, glossoptosis, and cleft palate define this sequence; the additional characteristic zygomatic/ear/fissure findings favor Treacher Collins."}, {"text": "Treacher Collins syndrome", "why": "This constellation is mandibulofacial dysostosis, commonly involving TCOF1 and abnormal cranial crest development/survival."}, {"text": "Spina bifida occulta", "why": "This is a posterior vertebral arch defect."}, {"text": "DiGeorge syndrome", "why": "DiGeorge is characterized by pharyngeal pouch dysfunction, thymic hypoplasia, hypocalcemia, and often conotruncal defects."}], "answer": 2}, {"id": "Q062", "deck": "emb", "ref": "slide-emb-22", "page": 22, "topic": "First-arch disorders", "stem": "A child with Treacher Collins syndrome has an affected parent with milder craniofacial findings. Which genetic pattern is most typical?", "options": [{"text": "Y-linked SHH mutation", "why": "This does not match typical Treacher Collins genetics."}, {"text": "Trisomy 13 in every case", "why": "Trisomy 13 is a classic holoprosencephaly association, not universal Treacher Collins etiology."}, {"text": "Autosomal recessive CFTR disease", "why": "CFTR causes cystic fibrosis rather than mandibulofacial dysostosis."}, {"text": "Mitochondrial inheritance of LIS1", "why": "LIS1 is a migration-disorder gene and this is not the typical Treacher Collins mechanism."}, {"text": "Autosomal dominant TCOF1-related disease with variable expression", "why": "TCOF1 is the most common association, and severity can vary; other genes/inheritance patterns exist, so this is the typical rather than exclusive pattern."}], "answer": 4}, {"id": "Q063", "deck": "emb", "ref": "slide-emb-22", "page": 22, "topic": "First-arch disorders", "stem": "The hearing loss in a child with external ear and ossicular malformations from Treacher Collins syndrome is most likely of which type?", "options": [{"text": "Pure central cortical deafness", "why": "Cortical deafness requires central auditory dysfunction rather than isolated ear/ossicle malformation."}, {"text": "An obligatory optic tract lesion", "why": "The optic tract transmits visual information, not sound."}, {"text": "A vestibular motor defect only", "why": "Vestibular dysfunction alone does not explain impaired ossicular sound conduction."}, {"text": "Conductive hearing loss", "why": "Malformed external/middle-ear structures impair sound transmission; a first-arch malformation need not damage cochlear hair cells to cause hearing loss."}, {"text": "A visual afferent defect", "why": "This affects pupillary responses and vision, not hearing."}], "answer": 3}, {"id": "Q064", "deck": "emb", "ref": "slide-emb-23", "page": 23, "topic": "First-arch disorders", "stem": "A newborn with a small mandible develops posterior tongue displacement, airway obstruction, and a U-shaped cleft palate. Which sequence best explains the findings?", "options": [{"text": "Stapes fixation causes mandibular absence", "why": "Ossicular fixation is not the initiating event in this sequence."}, {"text": "Forebrain cleavage failure invariably causes Pierre Robin sequence", "why": "Pierre Robin sequence does not require holoprosencephaly."}, {"text": "Micrognathia leads to glossoptosis, which prevents normal palatal shelf elevation/fusion", "why": "Pierre Robin sequence begins with mandibular hypoplasia; secondary tongue-position effects disrupt palatal development and can impair feeding/breathing."}, {"text": "Thymic absence causes the tongue to form from neural tube", "why": "Tongue formation is not explained by thymic absence."}, {"text": "Cleft palate causes caudal neuropore nonclosure", "why": "These are distinct developmental processes with no such sequence."}], "answer": 2}, {"id": "Q065", "deck": "emb", "ref": "slide-emb-23", "page": 23, "topic": "First-arch disorders", "stem": "In Pierre Robin sequence, what does glossoptosis mean?", "options": [{"text": "Failure of forebrain separation", "why": "That is holoprosencephaly."}, {"text": "Absence of the mandible", "why": "That is agnathia."}, {"text": "Posterior displacement of the tongue", "why": "The tongue falls posteriorly in the setting of micrognathia, contributing to airway obstruction and interference with palate formation."}, {"text": "Abnormally small head circumference", "why": "That is microcephaly."}, {"text": "Lateral cervical cyst formation", "why": "That commonly reflects a persistent second-cleft/cervical sinus remnant."}], "answer": 2}, {"id": "Q066", "deck": "emb", "ref": "slide-emb-24", "page": 24, "topic": "Pharyngeal architecture", "stem": "Which germ-layer relationship correctly describes a pharyngeal arch?", "options": [{"text": "Only neural crest with no mesoderm", "why": "Arch core includes mesoderm, particularly for musculature and endothelium."}, {"text": "Ectoderm externally, endoderm internally, mesoderm/neural crest mesenchyme in the core", "why": "Each arch contains skeletal, muscle, arterial, and nerve components in this layered organization."}, {"text": "Neural tube epithelium on both surfaces", "why": "The arch is not a folded neural tube."}, {"text": "Only mesoderm with no epithelium", "why": "Arches have distinct external and internal epithelial coverings."}, {"text": "Endoderm externally and ectoderm internally", "why": "This reverses the normal epithelial surfaces."}], "answer": 1}, {"id": "Q067", "deck": "emb", "ref": "slide-emb-24", "page": 24, "topic": "Pharyngeal architecture", "stem": "What distinguishes a pharyngeal pouch from a pharyngeal cleft?", "options": [{"text": "Pouches are internal endodermal outpocketings; clefts are external ectodermal grooves", "why": "This distinction predicts derivatives such as middle ear from first pouch and external meatus from first cleft."}, {"text": "Only pouches contain an arch artery", "why": "Arch arteries lie in arch mesenchyme, not as the defining feature of pouches."}, {"text": "Both are neural crest ganglia", "why": "They are epithelial structures rather than ganglia."}, {"text": "Pouches are external ectoderm and clefts internal endoderm", "why": "This reverses the correct relationship."}, {"text": "Both form the cerebral ventricles", "why": "Ventricles arise from the neural canal."}], "answer": 0}, {"id": "Q068", "deck": "emb", "ref": "slide-emb-24", "page": 24, "topic": "Pharyngeal architecture", "stem": "A persistent left ductus arteriosus is traced to the distal portion of which embryonic aortic arch?", "options": [{"text": "Third arch", "why": "Third contributes common carotids and proximal internal carotids."}, {"text": "Sixth arch", "why": "The left distal sixth arch forms ductus arteriosus; proximal sixth arches contribute pulmonary arteries. This extends the deck's artery-per-arch concept."}, {"text": "First arch", "why": "First arch contributes to maxillary arterial structures."}, {"text": "Second arch", "why": "Second arch has stapedial/hyoid arterial associations, much of which regress."}, {"text": "Fifth arch", "why": "The fifth is absent or regresses rather than forming the ductus."}], "answer": 1}, {"id": "Q069", "deck": "emb", "ref": "slide-emb-24", "page": 24, "topic": "Pharyngeal architecture", "stem": "Which artery derivative pairing is correct?", "options": [{"text": "Fourth arch — all pulmonary arteries and ductus", "why": "These are sixth-arch associations."}, {"text": "Second arch — adult left aortic arch as its principal derivative", "why": "Left fourth arch contributes the adult arch segment."}, {"text": "First arch — ductus arteriosus", "why": "Ductus derives from distal left sixth arch."}, {"text": "Third arch — common carotid and proximal internal carotid arteries", "why": "The third arch is carotid-associated; fourth forms left aortic arch/right proximal subclavian, while sixth is pulmonary/ductus-associated."}, {"text": "Sixth arch — external acoustic meatus", "why": "The meatus is first-cleft ectoderm, not an artery derivative."}], "answer": 3}, {"id": "Q070", "deck": "emb", "ref": "slide-emb-25", "page": 25, "topic": "Pouch derivatives", "stem": "Which structures develop from the first pharyngeal pouch?", "options": [{"text": "Thymus and inferior parathyroids", "why": "These come from third pouch."}, {"text": "Superior parathyroids and ultimobranchial body", "why": "These are fourth-pouch-associated derivatives."}, {"text": "Palatine tonsillar epithelium", "why": "This comes from second pouch."}, {"text": "External acoustic meatus and auricular skin", "why": "The external meatus is a first-cleft derivative."}, {"text": "Middle-ear cavity and auditory tube", "why": "The first pouch tubotympanic recess forms these endodermal epithelial spaces; the external canal instead comes from first cleft."}], "answer": 4}, {"id": "Q071", "deck": "emb", "ref": "slide-emb-25", "page": 25, "topic": "Pouch derivatives", "stem": "Palatine tonsillar epithelium arises from which pouch?", "options": [{"text": "Fourth pouch", "why": "Fourth pouch forms superior parathyroids and ultimobranchial-associated tissue."}, {"text": "Third pouch", "why": "Third pouch forms thymic epithelium and inferior parathyroids."}, {"text": "First pouch", "why": "First pouch forms middle ear and auditory tube."}, {"text": "First cleft", "why": "This forms the external acoustic meatus and is not a pouch."}, {"text": "Second pouch", "why": "Second pouch contributes tonsillar epithelium and crypts; lymphocytes subsequently populate the tissue from hematopoietic lineages."}], "answer": 4}, {"id": "Q072", "deck": "emb", "ref": "slide-emb-25", "page": 25, "topic": "Pouch derivatives", "stem": "A parathyroid gland is found near the thymus after abnormal embryonic descent. Which gland/pouch association best explains this location?", "options": [{"text": "Superior parathyroid from first pouch", "why": "Superior parathyroids derive from fourth pouch, not first."}, {"text": "Inferior parathyroid from first cleft", "why": "Clefts are ectodermal and do not form parathyroid glands."}, {"text": "Pineal gland from third pouch", "why": "Pineal tissue is diencephalic neuroectodermal."}, {"text": "Thyroid follicle from second arch cartilage", "why": "Thyroid follicular tissue arises from a midline endodermal diverticulum."}, {"text": "Inferior parathyroid from third pouch", "why": "Inferior parathyroids descend with thymic tissue from third pouch, traveling farther than fourth-pouch superior glands and allowing ectopic locations."}], "answer": 4}, {"id": "Q073", "deck": "emb", "ref": "slide-emb-25", "page": 25, "topic": "Pouch derivatives", "stem": "Which fourth-pouch-associated derivative supplies calcitonin-producing cells to the thyroid?", "options": [{"text": "Second cleft", "why": "This produces cervical sinus remnants when persistent."}, {"text": "Ultimobranchial body", "why": "The deck groups this with fourth pouch (sometimes termed fourth/fifth complex). Modern mammalian lineage evidence supports an endodermal C-cell origin; older charts often label them neural crest-derived."}, {"text": "First pouch tubotympanic recess", "why": "This forms middle-ear cavity and auditory tube."}, {"text": "Thyroglossal duct epithelium as the only C-cell source", "why": "The midline thyroid diverticulum primarily supplies follicular tissue; C-cell contribution is associated with the ultimobranchial body."}, {"text": "Third arch cartilage", "why": "This forms hyoid components, not the ultimobranchial body."}], "answer": 1}, {"id": "Q074", "deck": "emb", "ref": "slide-emb-25", "page": 25, "topic": "Pouch derivatives", "stem": "A neonate has tetany from hypocalcemia, recurrent viral/fungal infections, and a conotruncal cardiac defect. Imaging shows a small thymus. Which embryonic structures are primarily abnormal?", "options": [{"text": "Third and fourth pharyngeal pouches", "why": "The DiGeorge phenotype links thymic/parathyroid hypoplasia to T-cell deficiency and hypocalcemia, often in 22q11.2 deletion with conotruncal abnormalities."}, {"text": "Rostral neuropore alone", "why": "Closure failure causes anencephaly."}, {"text": "Mesencephalon alone", "why": "Midbrain development does not generate thymus and parathyroids."}, {"text": "First cleft alone", "why": "An isolated first-cleft defect affects external ear canal development."}, {"text": "Palatal shelves alone", "why": "Cleft palate does not by itself explain thymic/parathyroid deficiency."}], "answer": 0}, {"id": "Q075", "deck": "emb", "ref": "slide-emb-25", "page": 25, "topic": "Pouch derivatives", "stem": "Why does thymic hypoplasia in DiGeorge syndrome predispose to infection?", "options": [{"text": "Excess parathyroid hormone from absent glands", "why": "Absent/hypoplastic parathyroids reduce PTH and cause hypocalcemia."}, {"text": "Deficient T-cell maturation", "why": "Thymic epithelial development is necessary for normal T-cell maturation; third-pouch dysfunction can therefore impair cellular immunity."}, {"text": "Failure of all neutrophils to derive from ectoderm", "why": "Neutrophils arise from hematopoietic mesoderm, not ectoderm."}, {"text": "Failure of the lens to accommodate", "why": "This affects near vision and is unrelated to immune maturation."}, {"text": "Loss of retinal ganglion cells", "why": "These mediate visual signaling rather than immunity."}], "answer": 1}, {"id": "Q076", "deck": "emb", "ref": "slide-emb-25", "page": 25, "topic": "Pouch derivatives", "stem": "The tympanic membrane lies between the first cleft and first pouch. Which tissue arrangement best describes it?", "options": [{"text": "Only fourth-pouch endoderm", "why": "It is associated with first-cleft/first-pouch contact."}, {"text": "Only lens ectoderm", "why": "Lens tissue does not form the tympanic membrane."}, {"text": "Outer ectoderm, intervening mesenchyme, inner endoderm", "why": "The eardrum illustrates first membrane formation at the interface of external canal and middle-ear cavity."}, {"text": "Neural tube epithelium on both surfaces", "why": "Neither surface is neural tube epithelium."}, {"text": "Only neural crest neurons", "why": "The membrane is layered tissue rather than a sensory ganglion."}], "answer": 2}, {"id": "Q077", "deck": "emb", "ref": "slide-emb-26", "page": 26, "topic": "Clefts and neck remnants", "stem": "Which pharyngeal cleft normally persists as an adult structure?", "options": [{"text": "Second cleft as the normal thyroglossal duct", "why": "The second cleft normally disappears; thyroid descent follows a separate midline duct."}, {"text": "Fourth cleft as the superior parathyroids", "why": "Superior parathyroids derive from fourth pouch."}, {"text": "Third cleft as the thymus", "why": "Thymus derives from third pouch, not third cleft."}, {"text": "All four clefts as permanent skin openings", "why": "The lower clefts normally disappear, so persistent openings are abnormal."}, {"text": "First cleft", "why": "The first ectodermal cleft forms the external acoustic meatus; clefts 2–4 are normally overgrown and obliterated."}], "answer": 4}, {"id": "Q078", "deck": "emb", "ref": "slide-emb-26", "page": 26, "topic": "Clefts and neck remnants", "stem": "Overgrowth by the second arch normally eliminates the cervical sinus. Failure of this process most commonly leads to which lesion?", "options": [{"text": "Lateral branchial cleft cyst", "why": "Persistence of second-cleft/cervical sinus tissue produces a lateral neck cyst, sinus, or fistula."}, {"text": "Anencephaly", "why": "This results from rostral neural tube closure failure."}, {"text": "Pituitary macroadenoma", "why": "This is not a cervical sinus developmental remnant."}, {"text": "Lissencephaly", "why": "This results from abnormal neuronal migration."}, {"text": "Midline thyroglossal duct cyst", "why": "This results from persistence along thyroid descent, not the cervical sinus."}], "answer": 0}, {"id": "Q079", "deck": "emb", "ref": "slide-emb-27", "page": 27, "topic": "Clefts and neck remnants", "stem": "A teenager has a painless lateral neck mass just anterior to sternocleidomastoid. The mass enlarges after an upper respiratory infection and does not elevate with tongue protrusion. What is the most likely developmental origin?", "options": [{"text": "Unfused palatal shelves", "why": "This produces an oral-nasal communication."}, {"text": "Ectopic optic vesicle", "why": "This does not explain a typical lateral cervical mass."}, {"text": "Persistent second-cleft/cervical sinus remnant", "why": "The location and behavior are characteristic of a branchial cleft cyst."}, {"text": "Neural tube lumen", "why": "This forms CNS ventricular cavities, not a lateral cervical cyst."}, {"text": "Persistent thyroglossal duct", "why": "This usually creates a midline mass that moves with swallowing or tongue protrusion."}], "answer": 2}, {"id": "Q080", "deck": "emb", "ref": "slide-emb-27", "page": 27, "topic": "Clefts and neck remnants", "stem": "A developmental neck tract connects the skin to the pharynx through two patent openings. What is the correct term?", "options": [{"text": "Glossoptosis", "why": "This means posterior tongue displacement."}, {"text": "Cyst", "why": "A cyst has no patent opening to either surface."}, {"text": "Fistula", "why": "A fistula has two openings; a sinus has one opening, and a cyst is a closed cavity."}, {"text": "Meningocele", "why": "This specifically means herniated meninges and CSF."}, {"text": "Sinus", "why": "A sinus has only one patent opening."}], "answer": 2}, {"id": "Q081", "deck": "emb", "ref": "slide-emb-27", "page": 27, "topic": "Clefts and neck remnants", "stem": "A branchial remnant has one skin opening but ends blindly without pharyngeal communication. How should it be classified?", "options": [{"text": "Holoprosencephaly", "why": "This is a forebrain division disorder."}, {"text": "Thyroid agenesis", "why": "Absence of thyroid tissue does not classify a neck tract."}, {"text": "Sinus", "why": "A single opening with a blind end is a sinus."}, {"text": "Closed cyst", "why": "A closed cyst has no opening."}, {"text": "Complete fistula", "why": "A complete fistula communicates between two openings."}], "answer": 2}, {"id": "Q082", "deck": "emb", "ref": "slide-emb-28", "page": 28, "topic": "Thyroid development", "stem": "Thyroid follicular epithelium begins as an endodermal evagination at which site?", "options": [{"text": "Optic disc", "why": "This is the exit of retinal ganglion axons."}, {"text": "Neural crest at the caudal neuropore", "why": "This is not the origin of thyroid follicular epithelium."}, {"text": "Second external pharyngeal cleft", "why": "This is an ectodermal lateral groove, not the thyroid follicular primordium."}, {"text": "Foramen cecum region at the tongue base", "why": "The thyroid primordium appears near this midline site in week 4 and descends into the neck through the thyroglossal tract."}, {"text": "Calcarine sulcus", "why": "This is the adult primary visual cortex location."}], "answer": 3}, {"id": "Q083", "deck": "emb", "ref": "slide-emb-28", "page": 28, "topic": "Thyroid development", "stem": "Which statement best describes normal thyroid migration?", "options": [{"text": "It is formed by the first arch cartilage alone", "why": "The thyroid's follicular component is a midline endodermal derivative."}, {"text": "It remains connected to the tongue by a normally patent duct throughout life", "why": "The duct normally degenerates."}, {"text": "It descends from the tongue base, and the thyroglossal duct normally regresses", "why": "Regression leaves the thyroid separated from the original tongue-base site; persistent tissue can form a cyst or ectopic gland."}, {"text": "It descends with the thymus from third pouch as its sole origin", "why": "That describes thymic/inferior parathyroid migration, not follicular thyroid origin."}, {"text": "It ascends from the lumbosacral canal", "why": "The thyroid originates in the pharyngeal floor, not the spinal canal."}], "answer": 2}, {"id": "Q084", "deck": "emb", "ref": "slide-emb-28", "page": 28, "topic": "Thyroid development", "stem": "A surgeon finds a superior pyramidal extension of thyroid tissue along its embryonic descent route. What developmental remnant can explain this?", "options": [{"text": "Unfused secondary palatal shelf", "why": "This causes a palate defect."}, {"text": "Persistent second cervical sinus alone", "why": "This creates a lateral branchial remnant rather than a thyroid pyramidal extension."}, {"text": "Persistent distal thyroglossal tract tissue", "why": "The figure's pyramidal lobe is a thyroid-descent remnant; a cyst and lingual thyroid are other abnormalities related to this pathway."}, {"text": "Caudal neuropore patency", "why": "This concerns spinal neurulation rather than thyroid descent."}, {"text": "Failure of optic chiasm crossing", "why": "This is unrelated to thyroid anatomy."}], "answer": 2}, {"id": "Q085", "deck": "emb", "ref": "slide-emb-29", "page": 29, "topic": "Thyroid development", "stem": "A child has a midline neck mass that rises with swallowing and tongue protrusion. Which remnant most likely explains it?", "options": [{"text": "Nonfused maxillary prominence", "why": "This produces a facial cleft rather than a thyroglossal tract cyst."}, {"text": "Unclosed anterior neuropore", "why": "This causes anencephaly."}, {"text": "Persistent second pharyngeal cleft", "why": "This classically causes a lateral mass anterior to SCM."}, {"text": "Persistent neural crest ganglion", "why": "This is not the characteristic origin of this moving midline cyst."}, {"text": "Persistent thyroglossal duct", "why": "Attachment along the thyroid's migration path accounts for characteristic midline position and movement."}], "answer": 4}, {"id": "Q086", "deck": "emb", "ref": "slide-emb-29", "page": 29, "topic": "Thyroid development", "stem": "A tongue-base mass contains thyroid follicles, and no thyroid is visible in its usual neck location. Which developmental abnormality is most likely?", "options": [{"text": "First cleft persistence", "why": "This creates an external ear canal-related or lateral cervical anomaly, not thyroid follicles at tongue base."}, {"text": "Failure of thyroid descent causing lingual thyroid", "why": "Thyroid tissue can remain at the original tongue-base region; ectopic tissue may be the patient's only functioning thyroid."}, {"text": "Failure of neural tube closure", "why": "This does not generate ectopic thyroid tissue."}, {"text": "Excess descent of superior parathyroids", "why": "These are distinct endocrine tissues and do not form thyroid follicles."}, {"text": "Palatal shelf nonfusion alone", "why": "This does not explain thyroid tissue at its origin site."}], "answer": 1}, {"id": "Q087", "deck": "emb", "ref": "slide-emb-30", "page": 30, "topic": "Clefts and neck remnants", "stem": "Which examination comparison most strongly distinguishes common thyroglossal and branchial cleft cysts?", "options": [{"text": "Midline and moves with tongue/swallowing versus lateral anterior to SCM", "why": "These classic patterns distinguish thyroid-tract remnants from second-cleft/cervical sinus remnants, although real masses still require evaluation."}, {"text": "Both must be midline and move with tongue protrusion", "why": "This is not the usual branchial cleft pattern."}, {"text": "Branchial cysts always contain spinal cord", "why": "They are cervical epithelial remnants, not myelomeningoceles."}, {"text": "Location alone proves that a neck mass is benign", "why": "These patterns support a developmental diagnosis but do not prove all neck masses benign."}, {"text": "Thyroglossal cysts arise from first pharyngeal pouch", "why": "They arise from persistence of the thyroid migration tract."}], "answer": 0}, {"id": "Q088", "deck": "emb", "ref": "slide-emb-32", "page": 32, "topic": "Facial prominences", "stem": "The early face develops around the stomodeum from which five prominences?", "options": [{"text": "Two neural tubes and three optic cups", "why": "These do not define facial prominence organization."}, {"text": "Five pharyngeal pouches", "why": "Pouches are internal endodermal outpocketings, not the five facial prominences."}, {"text": "One frontonasal, two maxillary, and two mandibular prominences", "why": "This is the five-prominence organization; maxillary and mandibular prominences are first-arch components."}, {"text": "One thymic and four parathyroid prominences", "why": "These endocrine primordia do not form the five facial prominences."}, {"text": "Two frontonasal, one maxillary, and two thyroid prominences", "why": "This is not the normal five-prominence arrangement."}], "answer": 2}, {"id": "Q089", "deck": "emb", "ref": "slide-emb-32", "page": 32, "topic": "Facial prominences", "stem": "Which paired prominences form the lower lip and mandibular region?", "options": [{"text": "Lateral nasal prominences", "why": "These form the alae of the nose."}, {"text": "Mandibular prominences", "why": "The paired first-arch mandibular prominences contribute the lower face and jaw."}, {"text": "Palatal shelves alone", "why": "These form secondary palate rather than lower lip."}, {"text": "Optic vesicles", "why": "These contribute to the eyes rather than the lower face."}, {"text": "Medial nasal prominences alone", "why": "These form the intermaxillary segment, including philtrum and primary palate."}], "answer": 1}, {"id": "Q090", "deck": "emb", "ref": "slide-emb-32", "page": 32, "topic": "Facial prominences", "stem": "Which derivatives are correctly associated with maxillary prominences?", "options": [{"text": "Philtrum alone", "why": "The philtrum arises from merged medial nasal prominences within the intermaxillary segment."}, {"text": "Forehead alone", "why": "This is associated with frontonasal development."}, {"text": "Lower lip alone", "why": "This is a mandibular prominence derivative."}, {"text": "Alar portions of the nose alone", "why": "These are lateral nasal derivatives."}, {"text": "Cheeks and lateral upper lip", "why": "Maxillary prominences form these upper facial regions and also give rise to secondary palatal shelves."}], "answer": 4}, {"id": "Q091", "deck": "emb", "ref": "slide-emb-33", "page": 33, "topic": "Facial prominences", "stem": "Which prominences merge to form the intermaxillary segment and philtrum?", "options": [{"text": "Palatal shelves of the maxillary prominences only", "why": "These principally form secondary palate rather than the philtrum."}, {"text": "Medial nasal prominences", "why": "Their merger produces the intermaxillary segment, including central upper lip/philtrum and primary palate."}, {"text": "Lateral nasal prominences", "why": "These form the alae rather than the philtrum."}, {"text": "Mandibular prominences", "why": "These form the lower lip and jaw."}, {"text": "Second arch prominences", "why": "These are not the source of the intermaxillary segment."}], "answer": 1}, {"id": "Q092", "deck": "emb", "ref": "slide-emb-33", "page": 33, "topic": "Facial prominences", "stem": "An infant has a unilateral cleft of the upper lip lateral to the philtrum. Which fusion process most likely failed?", "options": [{"text": "First and second pharyngeal clefts", "why": "These are not the lip-forming prominences."}, {"text": "Maxillary with medial nasal prominence", "why": "Failure of this union produces the classic cleft lip."}, {"text": "Right and left palatal shelves only", "why": "This produces cleft palate, potentially with a normal lip."}, {"text": "Rostral and caudal neuropores", "why": "Neuropores close at opposite neural tube ends and do not fuse to form the lip."}, {"text": "Maxillary with mandibular prominence", "why": "Failure here is associated with lateral facial cleft/macrostomia, not the typical cleft lip."}], "answer": 1}, {"id": "Q093", "deck": "emb", "ref": "slide-emb-33", "page": 33, "topic": "Facial prominences", "stem": "Nasal placode-associated development generates medial and lateral nasal prominences. What do the lateral nasal prominences principally form?", "options": [{"text": "Philtrum of the upper lip", "why": "Philtrum is a medial nasal derivative."}, {"text": "Thymic epithelium", "why": "This is a third-pouch derivative."}, {"text": "Mandible", "why": "Mandibular prominences form the lower jaw."}, {"text": "Alar sides of the nose", "why": "The lateral nasal prominences contribute the nasal alae; medial prominences contribute the intermaxillary segment."}, {"text": "Secondary palate", "why": "Secondary palate comes from maxillary palatal shelves."}], "answer": 3}, {"id": "Q094", "deck": "emb", "ref": "slide-emb-34", "page": 34, "topic": "Palate development", "stem": "The hard palate anterior to the incisive foramen develops primarily from which source?", "options": [{"text": "Caudal neural tube", "why": "This forms spinal CNS structures."}, {"text": "Intermaxillary segment from merged medial nasal prominences", "why": "This is the primary palate; the incisive foramen is a key boundary with secondary palate."}, {"text": "Third pharyngeal pouch", "why": "This forms thymic/inferior parathyroid epithelium."}, {"text": "First pharyngeal cleft", "why": "This forms the external acoustic meatus."}, {"text": "Maxillary palatal shelves alone", "why": "These form secondary palate posterior to the incisive foramen."}], "answer": 1}, {"id": "Q095", "deck": "emb", "ref": "slide-emb-34", "page": 34, "topic": "Palate development", "stem": "Which structures form the secondary palate?", "options": [{"text": "Merged medial nasal prominences alone", "why": "These form the primary palate/intermaxillary segment."}, {"text": "Palatal shelves of the maxillary prominences", "why": "The shelves elevate and fuse, forming the remaining hard palate and the soft palate."}, {"text": "Lateral nasal prominences alone", "why": "These form nasal alae."}, {"text": "Mandibular prominences alone", "why": "These form lower lip and jaw."}, {"text": "Thyroglossal duct", "why": "This marks thyroid descent rather than palatal development."}], "answer": 1}, {"id": "Q096", "deck": "emb", "ref": "slide-emb-34", "page": 34, "topic": "Palate development", "stem": "Normal palatal fusion requires the secondary shelves to unite with each other and which additional structures?", "options": [{"text": "First cleft and external canal", "why": "These are lateral ear-related structures."}, {"text": "Caudal neuropore and spinal central canal", "why": "These are neural structures unrelated to palatal fusion."}, {"text": "Optic chiasm and ciliary ganglion", "why": "These structures participate in vision, not palate formation."}, {"text": "Thymus and inferior parathyroids", "why": "These descend in the neck and do not fuse with palatal shelves."}, {"text": "Primary palate and nasal septum", "why": "These fusions establish the roof of the mouth and separation of oral/nasal spaces."}], "answer": 4}, {"id": "Q097", "deck": "emb", "ref": "slide-emb-35", "page": 35, "topic": "Palate development", "stem": "Which order correctly describes secondary palate formation?", "options": [{"text": "First cleft persistence, second-cleft opening, palate regression", "why": "These events do not define normal palate formation."}, {"text": "Shelf fusion first, vertical growth second, tongue ascent last", "why": "This reverses the required morphologic order."}, {"text": "Mandibular fusion, thyroid ascent, calcarine folding", "why": "These are not the steps of palatal development."}, {"text": "Tongue permanent elevation, shelf fusion below it, neural tube closure", "why": "Persistent tongue interposition interferes with normal shelf fusion."}, {"text": "Vertical shelves beside tongue, tongue descent/shelf elevation, midline fusion", "why": "The shelves initially lie vertically; clearance by the descending tongue permits horizontal elevation and subsequent fusion."}], "answer": 4}, {"id": "Q098", "deck": "emb", "ref": "slide-emb-35", "page": 35, "topic": "Palate development", "stem": "Why can micrognathia lead to cleft palate even when the palatal shelves themselves initially form?", "options": [{"text": "It always destroys all pharyngeal pouches", "why": "Micrognathia does not require universal pouch loss."}, {"text": "It causes the thyroid to become the tongue", "why": "These are separate tissues and developmental processes."}, {"text": "The tongue remains interposed and prevents shelf elevation/fusion", "why": "Reduced mandibular space and glossoptosis interfere mechanically with normal shelf repositioning, as in Pierre Robin sequence."}, {"text": "It eliminates nasal retinal fibers", "why": "Visual crossing fibers do not regulate palatal elevation."}, {"text": "It converts secondary palate to neural crest ganglia", "why": "That is not a recognized tissue transformation."}], "answer": 2}, {"id": "Q099", "deck": "emb", "ref": "slide-emb-36", "page": 36, "topic": "Facial clefts", "stem": "A newborn has nasal regurgitation during feeds and later develops hypernasal speech. The upper lip is intact, but the oral and nasal cavities communicate through the palate. Which developmental failure explains this?", "options": [{"text": "Failure of optic tract formation", "why": "This causes visual defects rather than an oral-nasal communication."}, {"text": "Failure of maxillary–medial nasal lip fusion alone", "why": "This produces cleft lip; an isolated palatal opening points to palate fusion failure."}, {"text": "Caudal neuropore closure failure", "why": "This produces spinal dysraphism."}, {"text": "Second-cleft persistence", "why": "This creates a lateral cervical remnant."}, {"text": "Failure of palatal shelf fusion", "why": "An isolated cleft palate can occur with a normal lip and causes feeding, regurgitation, and speech problems."}], "answer": 4}, {"id": "Q100", "deck": "emb", "ref": "slide-emb-36", "page": 36, "topic": "Facial clefts", "stem": "Which landmark distinguishes primary from secondary palate clefts in the source diagrams?", "options": [{"text": "Foramen cecum", "why": "This marks thyroid origin at tongue base."}, {"text": "External acoustic meatus", "why": "This is a first-cleft-derived ear structure."}, {"text": "Incisive foramen", "why": "Primary palate is anterior to this landmark; secondary palate is posterior. Clefts can extend across this boundary."}, {"text": "Optic disc", "why": "This is a retinal landmark."}, {"text": "Calcarine sulcus", "why": "This is an occipital cortex landmark."}], "answer": 2}, {"id": "Q101", "deck": "emb", "ref": "slide-emb-37", "page": 37, "topic": "Facial clefts", "stem": "An oblique facial cleft extends from the upper lip toward the medial orbit along the nasolacrimal region. Which prominence union is classically abnormal?", "options": [{"text": "Maxillary and lateral nasal prominences", "why": "This related image-based application distinguishes an oblique facial cleft from the more common maxillary–medial nasal cleft lip."}, {"text": "Maxillary and medial nasal prominences only", "why": "Failure here produces classic cleft lip adjacent to the philtrum rather than the oblique nasolacrimal course."}, {"text": "Rostral neural folds", "why": "Closure failure causes a cranial neural tube defect."}, {"text": "Right and left palatal shelves only", "why": "This produces a palatal cleft without that facial course."}, {"text": "Third and fourth pharyngeal pouches", "why": "These form endocrine/immune derivatives, not the oblique face junction."}], "answer": 0}, {"id": "Q102", "deck": "emb", "ref": "slide-emb-37", "page": 37, "topic": "Facial clefts", "stem": "The image slide shows a rare median upper-lip cleft. Failure of merger of which structures best explains this location?", "options": [{"text": "The two medial nasal prominences", "why": "Their merger forms the central intermaxillary segment; failure can produce a median upper-lip cleft."}, {"text": "The two first pharyngeal clefts", "why": "Clefts do not merge to form central upper lip."}, {"text": "Mandibular with second arch prominence", "why": "This does not form the central upper lip."}, {"text": "The two secondary palatal shelves alone", "why": "This produces cleft palate rather than a median upper-lip gap."}, {"text": "Maxillary with medial nasal prominence on one side", "why": "This more typically produces a unilateral lateral cleft lip."}], "answer": 0}, {"id": "Q103", "deck": "emb", "ref": "slide-emb-37", "page": 37, "topic": "Facial clefts", "stem": "Which statement best accounts for the range of photographs showing isolated cleft lip, bilateral cleft lip, cleft palate, and combined defects?", "options": [{"text": "Bilateral cleft lip requires neural tube nonclosure", "why": "It instead reflects bilateral facial prominence fusion failure."}, {"text": "All clefts are explained by a persistent thyroglossal duct", "why": "That produces a neck remnant rather than facial/palatal nonunion."}, {"text": "All clefts must involve both lip and palate", "why": "Isolated defects are shown and are developmentally possible."}, {"text": "Lip and palate arise through related but distinct fusion events", "why": "Lip defects concern facial prominence union; palatal defects concern shelves and their connections. Either may occur alone or together."}, {"text": "A normal lip excludes cleft palate", "why": "Palatal shelves can fail independently."}], "answer": 3}, {"id": "Q104", "deck": "path", "ref": "slide-path-4", "page": 4, "topic": "Eye layers and fluids", "stem": "Which pair constitutes the fibrous outer coat of the eyeball?", "options": [{"text": "Sclera and cornea", "why": "Sclera provides protection and extraocular muscle attachment; transparent cornea is the major refractive surface."}, {"text": "Retina and optic disc", "why": "These belong to the inner neural system rather than the fibrous coat."}, {"text": "Choroid and retina", "why": "Choroid is vascular coat and retina is neural coat."}, {"text": "Lens and vitreous", "why": "These optical media are not the fibrous ocular coat."}, {"text": "Iris and ciliary body", "why": "Both are uveal structures of the middle layer."}], "answer": 0}, {"id": "Q105", "deck": "path", "ref": "slide-path-4", "page": 4, "topic": "Eye layers and fluids", "stem": "Which structures comprise the uvea?", "options": [{"text": "Conjunctiva, eyelid, and lacrimal gland", "why": "These are ocular surface/adnexal structures rather than uvea."}, {"text": "Vitreous, lens, and optic disc", "why": "This is not the uveal grouping."}, {"text": "Retina, optic nerve, and chiasm", "why": "These are neural visual structures."}, {"text": "Choroid, ciliary body, and iris", "why": "These form the middle vascular layer, supporting nutrition, accommodation/aqueous production, and pupil control."}, {"text": "Sclera, cornea, and lens", "why": "Sclera/cornea form the fibrous coat; lens is not uvea."}], "answer": 3}, {"id": "Q106", "deck": "path", "ref": "slide-path-4", "page": 4, "topic": "Eye layers and fluids", "stem": "Outer retinal photoreceptors receive much of their vascular nutrition from which structure?", "options": [{"text": "Corneal stroma", "why": "The normal cornea is avascular and is not the outer retinal vascular bed."}, {"text": "Lens capsule", "why": "The lens is avascular."}, {"text": "Choroid", "why": "The choroid/choriocapillaris supplies the outer retina; the central retinal artery primarily supplies the inner retina."}, {"text": "Scleral extraocular muscle insertions", "why": "These do not provide the principal photoreceptor blood supply."}, {"text": "Optic chiasm", "why": "The chiasm is a neural crossing structure, not retinal vascular supply."}], "answer": 2}, {"id": "Q107", "deck": "path", "ref": "slide-path-4", "page": 4, "topic": "Eye layers and fluids", "stem": "Which part of the eye produces aqueous humor and participates in accommodation?", "options": [{"text": "Sclera", "why": "Sclera provides a protective coat and muscle attachment."}, {"text": "Ciliary body", "why": "Ciliary processes produce aqueous, and ciliary muscle changes zonular tension to alter lens shape."}, {"text": "Optic disc", "why": "The disc is where retinal axons and vessels enter/exit."}, {"text": "Fovea", "why": "Fovea specializes in high-acuity vision."}, {"text": "Choroid alone", "why": "Choroid supplies outer retina but does not perform ciliary accommodation."}], "answer": 1}, {"id": "Q108", "deck": "path", "ref": "slide-path-4", "page": 4, "topic": "Eye layers and fluids", "stem": "Aqueous humor normally flows from the posterior chamber through the pupil to the anterior chamber. Which route is the major conventional outflow pathway afterward?", "options": [{"text": "Trabecular meshwork to canal of Schlemm", "why": "This related anatomy explains why impaired anterior chamber angle drainage can increase intraocular pressure; aqueous originates in ciliary processes."}, {"text": "Corneal epithelium directly to the nasal cavity", "why": "Tears drain nasally, but intraocular aqueous uses a different route."}, {"text": "Lens capsule to the vitreous only", "why": "The lens capsule is not the conventional outflow system."}, {"text": "Optic nerve to the cerebral aqueduct", "why": "This is not the normal aqueous drainage pathway."}, {"text": "Retinal vein to the fourth ventricle", "why": "Retinal blood drainage is distinct from aqueous outflow."}], "answer": 0}, {"id": "Q109", "deck": "path", "ref": "slide-path-4", "page": 4, "topic": "Eye layers and fluids", "stem": "Which statement correctly distinguishes the posterior chamber from the vitreous chamber in the eye diagram?", "options": [{"text": "Both terms mean the cerebral third ventricle", "why": "These are intraocular compartments."}, {"text": "Anterior chamber normally contains solid lens tissue throughout", "why": "It normally contains aqueous, with lens located posterior to iris."}, {"text": "Vitreous chamber lies between cornea and iris", "why": "That is the anterior aqueous chamber."}, {"text": "Posterior chamber lies between iris and lens; vitreous chamber lies behind the lens", "why": "The small aqueous posterior chamber is not the large postremal/vitreous compartment; anterior chamber lies between cornea and iris."}, {"text": "Posterior chamber is the entire space behind the retina", "why": "The chamber is anterior to the lens, not behind retina."}], "answer": 3}, {"id": "Q110", "deck": "path", "ref": "slide-path-4", "page": 4, "topic": "Eye layers and fluids", "stem": "Which landmark marks the anterior limit of the photosensitive retina in the source cross-section?", "options": [{"text": "Optic disc", "why": "This is the posterior axon/vessel exit, not anterior retinal margin."}, {"text": "Scleral venous sinus", "why": "This is an aqueous drainage structure at the anterior angle."}, {"text": "Fovea centralis", "why": "This is the macular acuity center."}, {"text": "Superior orbital fissure", "why": "This is a bony orbital opening, not retinal margin."}, {"text": "Ora serrata", "why": "The serrated retinal margin marks transition toward nonphotosensitive ciliary epithelium; vitreous occupies the large compartment behind the lens."}], "answer": 4}, {"id": "Q111", "deck": "path", "ref": "slide-path-4", "page": 4, "topic": "Eye layers and fluids", "stem": "A patient develops flashes, floaters, and a curtain-like peripheral visual shadow. A retinal tear allows fluid to separate neural retina from which adjacent layer?", "options": [{"text": "Iris dilator muscle", "why": "This lies in anterior iris rather than under retina."}, {"text": "Optic chiasm", "why": "This is intracranial and is not the local retinal interface."}, {"text": "Corneal epithelium", "why": "This is at the anterior ocular surface, not adjacent to neural retina."}, {"text": "Lens capsule", "why": "This surrounds the lens, not neural retina."}, {"text": "Retinal pigment epithelium", "why": "Rhegmatogenous detachment separates neurosensory retina from RPE, threatening photoreceptor support; this applies the illustrated retinal/choroidal layering."}], "answer": 4}, {"id": "Q112", "deck": "path", "ref": "slide-path-4", "page": 4, "topic": "Eye layers and fluids", "stem": "A patient has abrupt eye pain, halos, nausea, a mid-dilated pupil, and high intraocular pressure in a shallow anterior chamber. Which mechanism best fits acute angle closure?", "options": [{"text": "Primary loss of foveal cones alone", "why": "That does not account for acute anterior chamber pressure elevation."}, {"text": "Relaxation of the lens zonules as the only abnormality", "why": "Normal accommodation alone does not produce acute angle closure."}, {"text": "Excess CSF in the optic nerve sheath as the sole mechanism", "why": "That explains papilledema, not the typical painful high-pressure angle-closure presentation."}, {"text": "Left optic tract infarction", "why": "That causes a homonymous field defect rather than this painful anterior ocular syndrome."}, {"text": "Obstruction of aqueous access to the trabecular drainage angle", "why": "Impaired aqueous outflow rapidly raises pressure, linking chamber/iris anatomy to a high-yield ocular emergency."}], "answer": 4}, {"id": "Q113", "deck": "path", "ref": "slide-path-5", "page": 5, "topic": "Optics and accommodation", "stem": "Which structure accounts for approximately two-thirds of the eye's refractive power?", "options": [{"text": "Iris sphincter", "why": "This controls pupil diameter rather than providing most refraction."}, {"text": "Optic nerve", "why": "This transmits retinal signals rather than refracting light."}, {"text": "Sclera", "why": "Opaque sclera is protective and is not the major optical surface."}, {"text": "Lens alone", "why": "Lens is adjustable but contributes less than the cornea to total power."}, {"text": "Cornea", "why": "The air-cornea interface supplies most fixed refractive power; the lens provides adjustable focusing."}], "answer": 4}, {"id": "Q114", "deck": "path", "ref": "slide-path-5", "page": 5, "topic": "Optics and accommodation", "stem": "An object lies above and to the right of fixation. How is its retinal image oriented relative to visual space?", "options": [{"text": "Vertically inverted but never horizontally reversed", "why": "The image is reversed along both axes."}, {"text": "Upright and unreversed", "why": "This ignores the inversion produced by ocular optics."}, {"text": "Only color is reversed", "why": "Color inversion is not the geometric optical transformation."}, {"text": "Each eye projects the entire image only onto its nasal retina", "why": "Each retina receives both nasal and temporal field information."}, {"text": "Inverted vertically and reversed horizontally", "why": "The ocular optical system reverses image orientation, so superior field projects inferiorly and right field onto left retinal halves."}], "answer": 4}, {"id": "Q115", "deck": "path", "ref": "slide-path-5", "page": 5, "topic": "Optics and accommodation", "stem": "A myopic eye focuses parallel rays in front of the retina. Which lens corrects this high-yield refractive problem?", "options": [{"text": "Diverging concave lens", "why": "A negative lens reduces effective convergence, moving the focus posteriorly onto the retina."}, {"text": "Opaque plano lens", "why": "Blocking light does not correct focal position."}, {"text": "No optical correction can change the focal plane", "why": "Appropriate external lenses can alter incoming ray convergence."}, {"text": "A lens that increases refractive power without limit", "why": "Increased convergence worsens focus anterior to the retina."}, {"text": "Converging convex lens", "why": "This increases convergence and is used for hyperopic rather than myopic correction."}], "answer": 0}, {"id": "Q116", "deck": "path", "ref": "slide-path-5", "page": 5, "topic": "Optics and accommodation", "stem": "An older adult gradually needs reading glasses despite preserved distance vision. What change most directly causes typical presbyopia?", "options": [{"text": "Complete loss of all rods", "why": "Rod loss affects dim-light vision rather than isolated age-related near focusing."}, {"text": "Failure of nasal fibers to cross", "why": "Chiasmal dysfunction causes field defects rather than presbyopia."}, {"text": "New absence of the optic disc", "why": "The optic disc remains anatomically present and is unrelated to lens stiffness."}, {"text": "Excessive convergence of both eyes at rest as the defining mechanism", "why": "Typical presbyopia is lens accommodation loss."}, {"text": "Reduced lens elasticity and accommodation", "why": "A less deformable lens cannot round adequately for near focus despite ciliary activation; this extends the slide's adjustable-focus concept."}], "answer": 4}, {"id": "Q117", "deck": "path", "ref": "slide-path-6", "page": 6, "topic": "Optics and accommodation", "stem": "When shifting from a distant sign to a nearby book, what happens to ciliary muscle, zonules, and lens?", "options": [{"text": "Muscle contracts, zonules relax, lens rounds", "why": "Parasympathetic ciliary contraction reduces suspensory tension, increasing lens curvature and refractive power."}, {"text": "Muscle relaxes, zonules relax, lens rounds", "why": "Ciliary relaxation normally increases zonular tension."}, {"text": "Muscle relaxes, zonules tighten, lens flattens", "why": "This is the distance-vision state."}, {"text": "Muscle contracts, zonules tighten, lens flattens", "why": "This combines contraction with the wrong tension/shape response."}, {"text": "Lens becomes opaque as the normal response", "why": "Opacity is not part of normal accommodation."}], "answer": 0}, {"id": "Q118", "deck": "path", "ref": "slide-path-6", "page": 6, "topic": "Optics and accommodation", "stem": "Which sequence supplies parasympathetic accommodation?", "options": [{"text": "CN VI directly to the lens", "why": "VI innervates lateral rectus, and the lens itself is not a muscle."}, {"text": "CN VII to pterygopalatine ganglion to ciliary muscle", "why": "This ganglion supplies lacrimal/nasal pathways, not lens accommodation."}, {"text": "CN II to superior cervical ganglion to long ciliary nerves", "why": "II is sensory; the superior cervical/long ciliary route is sympathetic."}, {"text": "CN III to ciliary ganglion to short ciliary nerves", "why": "Preganglionic oculomotor fibers synapse in ciliary ganglion; postganglionic short ciliary fibers activate ciliary muscle."}, {"text": "CN IX to otic ganglion to ciliary muscle", "why": "This pathway supplies parotid secretion rather than accommodation."}], "answer": 3}, {"id": "Q119", "deck": "path", "ref": "slide-path-6", "page": 6, "topic": "Optics and accommodation", "stem": "During normal distance fixation, which configuration is expected?", "options": [{"text": "Contracted ciliary muscle, slack zonules, rounded lens", "why": "This is near accommodation."}, {"text": "Relaxed ciliary muscle, taut zonules, flattened lens", "why": "Relaxation increases zonular traction and reduces lens curvature/power."}, {"text": "Permanent contraction of extraocular muscles replaces lens focusing", "why": "Extraocular movement and lens accommodation have different functions."}, {"text": "Slack zonules and low lens curvature as the standard pair", "why": "Slack zonules permit increased curvature."}, {"text": "Contracted ciliary muscle and maximal lens flattening", "why": "Contraction normally allows rounding rather than flattening."}], "answer": 1}, {"id": "Q120", "deck": "path", "ref": "slide-path-7", "page": 7, "topic": "Pupillary autonomics", "stem": "Which muscle and pathway constrict the pupil?", "options": [{"text": "Lateral rectus through CN VI", "why": "This abducts the eye rather than constricting the pupil."}, {"text": "Sphincter pupillae through parasympathetic CN III/ciliary ganglion/short ciliary nerves", "why": "Circular sphincter contraction produces miosis; its efferent route differs from sympathetic dilation."}, {"text": "Ciliary muscle through CN II motor fibers", "why": "II is afferent and does not carry motor fibers to ciliary muscle."}, {"text": "Orbicularis oculi through CN VII", "why": "This closes eyelids rather than changing pupil diameter."}, {"text": "Dilator pupillae through superior cervical ganglion", "why": "This produces mydriasis, not miosis."}], "answer": 1}, {"id": "Q121", "deck": "path", "ref": "slide-path-7", "page": 7, "topic": "Pupillary autonomics", "stem": "Postganglionic sympathetic fibers from which ganglion principally reach dilator pupillae through long ciliary nerves?", "options": [{"text": "Submandibular ganglion", "why": "This supplies submandibular/sublingual glands."}, {"text": "Otic ganglion", "why": "This parasympathetic ganglion supplies parotid secretion."}, {"text": "Superior cervical ganglion", "why": "These fibers travel along the carotid/orbital pathway and chiefly through long ciliary nerves to produce mydriasis."}, {"text": "Pterygopalatine ganglion", "why": "This supplies lacrimal and nasal/palatal glands rather than the principal pupil dilator pathway."}, {"text": "Ciliary ganglion as a sympathetic synapse", "why": "Ciliary ganglion is the parasympathetic synapse; sympathetic fibers can pass without synapsing."}], "answer": 2}, {"id": "Q122", "deck": "path", "ref": "slide-path-7", "page": 7, "topic": "Pupillary autonomics", "stem": "A patient has mild left ptosis, a smaller left pupil, and reduced facial sweating after disruption of cervical sympathetic fibers. Which ocular muscle is directly underactive?", "options": [{"text": "Left sphincter pupillae", "why": "Loss of sphincter function would dilate the pupil."}, {"text": "Left dilator pupillae", "why": "Loss of sympathetic dilation causes miosis in Horner syndrome; the deck's sympathetic iris pathway explains the pupil finding."}, {"text": "Right medial rectus", "why": "Its dysfunction affects eye adduction rather than the left pupil."}, {"text": "Left lateral rectus", "why": "Its dysfunction causes abduction weakness rather than miosis."}, {"text": "Left orbicularis oculi", "why": "This is facial-nerve-mediated eyelid closure, not iris dilation."}], "answer": 1}, {"id": "Q123", "deck": "path", "ref": "slide-path-7", "page": 7, "topic": "Pupillary autonomics", "stem": "After topical muscarinic blockade, a patient's pupil is dilated and near focusing is impaired. Which muscles have been inhibited?", "options": [{"text": "Sphincter pupillae and ciliary muscle", "why": "Muscarinic blockade prevents parasympathetic miosis and accommodation, causing mydriasis and cycloplegia."}, {"text": "Dilator pupillae and lateral rectus", "why": "Dilator is adrenergic and lateral rectus is skeletal motor muscle."}, {"text": "Orbicularis oculi and medial rectus", "why": "These are skeletal muscles, not the principal topical muscarinic targets."}, {"text": "Retinal ganglion cells and sclera", "why": "Neither is the contractile muscarinic effector pair described."}, {"text": "Superior oblique and inferior oblique", "why": "These extraocular muscles are not responsible for pupil constriction or lens accommodation."}], "answer": 0}, {"id": "Q124", "deck": "path", "ref": "slide-path-7", "page": 7, "topic": "Pupillary autonomics", "stem": "The ciliary ganglion receives parasympathetic, sympathetic, and sensory roots in the diagram. Which fibers normally synapse there?", "options": [{"text": "All somatic motor fibers to extraocular muscles", "why": "These reach skeletal muscles directly rather than synapsing in an autonomic ganglion."}, {"text": "All sensory fibers from nasociliary nerve", "why": "These sensory cell bodies lie in trigeminal ganglion, not ciliary ganglion."}, {"text": "All sympathetic fibers from superior cervical ganglion", "why": "These are already postganglionic and do not synapse again in ciliary ganglion."}, {"text": "Preganglionic parasympathetic fibers from CN III", "why": "Sympathetic postganglionic and sensory fibers pass through without using this ganglion as their autonomic synapse."}, {"text": "Retinal ganglion-cell axons", "why": "Retinal visual axons travel in II, not through ciliary ganglion as a relay."}], "answer": 3}, {"id": "Q125", "deck": "path", "ref": "slide-path-8", "page": 8, "topic": "Retina and fundus", "stem": "Which retinal neurons send axons into the optic nerve?", "options": [{"text": "Horizontal cells directly", "why": "These are retinal interneurons."}, {"text": "Retinal pigment epithelial cells", "why": "These support photoreceptors rather than forming the optic nerve."}, {"text": "Bipolar cells directly", "why": "Bipolar cells relay within retina to ganglion cells."}, {"text": "Ganglion cells", "why": "Retinal ganglion-cell axons converge at the optic disc to form CN II."}, {"text": "Photoreceptors directly", "why": "Photoreceptors signal through retinal circuits rather than extending their axons as CN II."}], "answer": 3}, {"id": "Q126", "deck": "path", "ref": "slide-path-8", "page": 8, "topic": "Retina and fundus", "stem": "Which retinal region has the highest cone density and greatest visual acuity?", "options": [{"text": "Optic disc", "why": "The disc has no photoreceptors."}, {"text": "Sclera", "why": "Sclera is not a neural retinal region."}, {"text": "Fovea centralis in the macula lutea", "why": "The fovea specializes in detailed central vision, whereas peripheral retina is more rod-rich."}, {"text": "Ciliary processes", "why": "These produce aqueous, not photoreceptor-mediated vision."}, {"text": "Ora serrata", "why": "This peripheral boundary does not have maximal cone density."}], "answer": 2}, {"id": "Q127", "deck": "path", "ref": "slide-path-8", "page": 8, "topic": "Retina and fundus", "stem": "Why does the optic disc create a physiological blind spot?", "options": [{"text": "It lacks photoreceptors where axons and vessels traverse the retina", "why": "The disc is an exit/entry site, so incident light at that retinal location cannot be directly detected."}, {"text": "It has the highest cone density", "why": "That describes foveal specialization, not the disc."}, {"text": "Its lens is opaque", "why": "The lens is a separate structure."}, {"text": "Nasal retinal fibers are absent from the entire eye", "why": "Nasal fibers are normally present and cross at chiasm."}, {"text": "The occipital cortex ignores all central vision", "why": "Central vision has extensive cortical representation."}], "answer": 0}, {"id": "Q128", "deck": "path", "ref": "slide-path-8", "page": 8, "topic": "Retina and fundus", "stem": "A patient sees well in daylight but poorly in dim illumination. Which photoreceptor population is most relevant to this high-yield retinal distinction?", "options": [{"text": "Scleral fibroblasts", "why": "These provide structural support rather than phototransduction."}, {"text": "Ciliary muscle cells", "why": "These focus the lens rather than detect light."}, {"text": "Rods", "why": "Rods are highly sensitive for scotopic vision; cones support color and high spatial acuity, especially in fovea."}, {"text": "Foveal cones exclusively", "why": "Cones mediate photopic/color acuity rather than the main dim-light function."}, {"text": "Optic disc photoreceptors", "why": "There are no photoreceptors at the disc."}], "answer": 2}, {"id": "Q129", "deck": "path", "ref": "slide-path-8", "page": 8, "topic": "Retina and fundus", "stem": "Light activates rhodopsin in a rod. Which downstream change normally occurs?", "options": [{"text": "Increased cGMP opens more channels and depolarizes the rod", "why": "This is opposite the normal light response."}, {"text": "All retinal ganglion axons stop existing", "why": "Axonal structure is not eliminated by light exposure."}, {"text": "Reduced cGMP closes cation channels and hyperpolarizes the rod", "why": "Phototransduction activates transducin/phosphodiesterase, lowering cGMP and decreasing glutamate release; darkness keeps cGMP-gated channels open."}, {"text": "Action potentials begin in the lens capsule", "why": "The lens does not perform neuronal phototransduction."}, {"text": "The optic disc gains new cones immediately", "why": "The normal disc remains photoreceptor-free."}], "answer": 2}, {"id": "Q130", "deck": "path", "ref": "slide-path-9", "page": 9, "topic": "Retina and fundus", "stem": "On a normal fundus examination, which landmark is typically nasal to the macula and has central retinal vessels emerging from it?", "options": [{"text": "Optic disc", "why": "The source fundus images show the disc/vessels nasally and the macula temporally; the macular center is fovea."}, {"text": "Ciliary ganglion", "why": "The ganglion lies outside the eyeball, not on fundus examination."}, {"text": "Fovea", "why": "The fovea lies within the macula and does not have the optic nerve/vessel exit configuration."}, {"text": "Iris dilator", "why": "This is anterior iris muscle rather than a fundus structure."}, {"text": "Cornea", "why": "The cornea is anterior and is not a posterior fundus landmark."}], "answer": 0}, {"id": "Q131", "deck": "path", "ref": "slide-path-9", "page": 9, "topic": "Retina and fundus", "stem": "A patient has profound central visual impairment but relatively preserved peripheral fields. Which retinal site is the best match?", "options": [{"text": "Entire optic nerve transection", "why": "That would cause much more extensive monocular visual loss."}, {"text": "Macula/fovea", "why": "Damage to central high-acuity retina impairs reading and detailed fixation while peripheral retina can remain functional."}, {"text": "Corneal limbus only", "why": "This is the corneoscleral boundary and not central neural retina."}, {"text": "Ciliary body only", "why": "This primarily affects aqueous/accommodation rather than a selective central retinal defect."}, {"text": "Optic disc as a normal physiological finding", "why": "The normal blind spot does not explain new profound central loss."}], "answer": 1}, {"id": "Q132", "deck": "path", "ref": "slide-path-10", "page": 10, "topic": "Papilledema", "stem": "A patient with headache and vomiting has bilateral swollen optic discs with blurred margins and obscured vessels, resembling the source photograph. What does papilledema specifically signify?", "options": [{"text": "Any optic disc edema regardless of cause", "why": "Not every swollen disc is papilledema; optic neuritis and ischemic neuropathy can also cause edema."}, {"text": "Primary paralysis of dilator pupillae", "why": "That produces a pupil abnormality, not papilledema."}, {"text": "Normal macular pigmentation", "why": "The photograph concerns optic nerve head swelling rather than normal macula."}, {"text": "Physiological absence of photoreceptors at the disc", "why": "That creates the normal blind spot, not swelling."}, {"text": "Optic disc edema caused by elevated intracranial pressure", "why": "Papilledema is a pressure-related diagnosis, typically bilateral; other causes of disc edema must be distinguished."}], "answer": 4}, {"id": "Q133", "deck": "path", "ref": "slide-path-10", "page": 10, "topic": "Papilledema", "stem": "How can elevated CSF pressure be transmitted to the optic nerve head?", "options": [{"text": "Through the aqueous drainage canal directly into the brain", "why": "Canal of Schlemm drains aqueous and is not the CSF conduit."}, {"text": "Through the subarachnoid space surrounding the optic nerve", "why": "The optic nerve is a CNS extension with meningeal coverings; raised pressure can impair axoplasmic transport at the disc."}, {"text": "Through the external acoustic canal", "why": "The ear canal is unrelated to optic nerve sheath pressure."}, {"text": "Through the corneal epithelium alone", "why": "This is not continuous with the optic subarachnoid space."}, {"text": "Through the lens zonules", "why": "Zonules alter lens shape and do not transmit intracranial CSF pressure."}], "answer": 1}, {"id": "Q134", "deck": "path", "ref": "slide-path-10", "page": 10, "topic": "Papilledema", "stem": "Which field change is commonly associated with early papilledema?", "options": [{"text": "A permanent increase in foveal cone density", "why": "This is not a field defect and does not occur as the defining response to edema."}, {"text": "Obligate bitemporal hemianopia", "why": "That suggests chiasmal crossing-fiber injury rather than the typical early disc finding."}, {"text": "Obligate homonymous superior quadrantanopia", "why": "That points to temporal optic radiations."}, {"text": "Complete loss of the left field in both eyes in every case", "why": "That is a right postchiasmal pattern, not required by papilledema."}, {"text": "Enlargement of the physiological blind spot", "why": "Disc swelling can enlarge the blind spot; central acuity may be relatively preserved early, so a normal reading test does not exclude it."}], "answer": 4}, {"id": "Q135", "deck": "path", "ref": "slide-path-12", "page": 12, "topic": "Retinal projection", "stem": "The left visual hemifield projects onto which retinal halves?", "options": [{"text": "Left temporal retina and right nasal retina", "why": "These carry the right visual hemifield."}, {"text": "Both nasal hemiretinae", "why": "Both nasal halves together represent both temporal fields, not one shared hemifield."}, {"text": "Only the left eye", "why": "Both eyes receive much of the left hemifield within binocular overlap."}, {"text": "Left nasal retina and right temporal retina", "why": "Left space maps to the right half of each retina: nasal half in the left eye and temporal half in the right eye."}, {"text": "Both temporal hemiretinae", "why": "These represent each eye's nasal field rather than one shared hemifield."}], "answer": 3}, {"id": "Q136", "deck": "path", "ref": "slide-path-12", "page": 12, "topic": "Retinal projection", "stem": "A stimulus in the superior visual field projects primarily onto which retinal region?", "options": [{"text": "Optic disc only", "why": "The optic disc has no photoreceptors and is not the entire superior-field projection."}, {"text": "Superior retina", "why": "Superior retina represents inferior visual space."}, {"text": "Lens epithelium", "why": "The lens focuses light but does not encode retinal fields."}, {"text": "Inferior retina", "why": "Vertical inversion places superior visual space on inferior retinal tissue, whose temporal radiation pathway includes Meyer's loop."}, {"text": "Ciliary body", "why": "This is not the neural image detection region."}], "answer": 3}, {"id": "Q137", "deck": "path", "ref": "slide-path-12", "page": 12, "topic": "Retinal projection", "stem": "A target appears in the right inferior binocular visual quadrant. Which retinal regions receive its image?", "options": [{"text": "Both optic discs", "why": "Discs contain no photoreceptors and cannot receive the normal image signal."}, {"text": "Left superior nasal and right superior temporal retina", "why": "These carry the left inferior field."}, {"text": "Both inferior nasal retinal quadrants", "why": "This has both incorrect vertical mapping and incorrect binocular grouping."}, {"text": "Left inferior temporal and right inferior nasal retina", "why": "These carry the right superior field, not inferior."}, {"text": "Left superior temporal retina and right superior nasal retina", "why": "Right field maps to left retinal halves, and inferior field maps superiorly. Nasal right-eye fibers cross to join left temporal-eye fibers in the left pathway."}], "answer": 4}, {"id": "Q138", "deck": "path", "ref": "slide-path-13", "page": 13, "topic": "Retinal projection", "stem": "The temporal visual field of the right eye is detected by which hemiretina?", "options": [{"text": "Left nasal retina only", "why": "The question specifies projection in the right eye."}, {"text": "Right nasal hemiretina", "why": "Horizontal image reversal maps temporal visual space onto nasal retina."}, {"text": "Right temporal hemiretina", "why": "This detects the right eye's nasal field."}, {"text": "Right optic disc", "why": "The optic disc is photoreceptor-free."}, {"text": "Entire left occipital cortex directly without retina", "why": "Visual signals are first transduced in retina before central processing."}], "answer": 1}, {"id": "Q139", "deck": "path", "ref": "slide-path-13", "page": 13, "topic": "Retinal projection", "stem": "Which statement about binocular fields is correct?", "options": [{"text": "Each eye samples both hemifields, with central overlap between the eyes", "why": "Nasal and temporal retinal halves in each eye receive opposite visual-space halves; the central region is binocular."}, {"text": "Temporal fields project to temporal retina", "why": "Temporal space projects to nasal retina."}, {"text": "The right eye sees only right space", "why": "This confuses eye laterality with visual hemifield."}, {"text": "Binocular overlap means neither eye has a blind spot", "why": "Each optic disc still lacks photoreceptors; overlapping information helps compensate."}, {"text": "The left eye sees only left space", "why": "Each eye sees both hemifields to differing extents."}], "answer": 0}, {"id": "Q140", "deck": "path", "ref": "slide-path-14", "page": 14, "topic": "Retinocortical pathway", "stem": "Which sequence correctly carries conscious visual information to primary cortex?", "options": [{"text": "Retina, optic nerve, chiasm, optic tract, LGN, optic radiations, V1", "why": "This is the deck's principal retinogeniculocalcarine pathway; not all retinal fibers terminate in LGN."}, {"text": "Retina, CN III, ciliary ganglion, LGN, V1", "why": "III/ciliary ganglion carry ocular motor parasympathetic output, not conscious visual afference."}, {"text": "Retina, optic radiations, optic nerve, chiasm, LGN", "why": "This reverses the central order."}, {"text": "Retina, medial geniculate nucleus, auditory cortex", "why": "Medial geniculate relays auditory rather than principal visual information."}, {"text": "Cornea, V1 nerve, spinal trigeminal nucleus, V1 cortex", "why": "This confuses corneal somatic sensation with visual signaling and two different uses of V1."}], "answer": 0}, {"id": "Q141", "deck": "path", "ref": "slide-path-14", "page": 14, "topic": "Retinocortical pathway", "stem": "Which thalamic nucleus is the principal relay for the conscious visual pathway?", "options": [{"text": "Lateral geniculate nucleus", "why": "Most optic tract fibers relay in LGN before reaching cortex through optic radiations."}, {"text": "Ventral posteromedial nucleus", "why": "This relays much face somatic sensation/taste-related input."}, {"text": "Medial geniculate nucleus", "why": "This is the auditory thalamic relay."}, {"text": "Anterior nucleus", "why": "This is associated with limbic circuitry rather than the principal visual relay."}, {"text": "Ventral posterolateral nucleus", "why": "This relays much body somatic sensation."}], "answer": 0}, {"id": "Q142", "deck": "path", "ref": "slide-path-14", "page": 14, "topic": "Retinocortical pathway", "stem": "A patient with bilateral occipital injury lacks conscious vision but retains pupillary constriction to light. Which pathway explains the preserved reflex?", "options": [{"text": "Corneal V1 sensation substitutes for retinal light detection", "why": "Corneal touch afference is distinct from the pupillary light afferent limb."}, {"text": "CN III transmits retinal images directly to cortex", "why": "III supplies motor/parasympathetic output rather than retinal afferent vision."}, {"text": "Lens zonules generate the consensual reflex", "why": "Zonules are suspensory structures, not a central reflex pathway."}, {"text": "Retinal projections to pretectal midbrain bypass the principal LGN–V1 route", "why": "The light reflex does not require intact conscious visual cortex, unlike cortical perception of the image."}, {"text": "All light reflex fibers must first synapse in V1", "why": "This would make the preserved reflex impossible and is anatomically incorrect."}], "answer": 3}, {"id": "Q143", "deck": "path", "ref": "slide-path-15", "page": 15, "topic": "Chiasm and optic tracts", "stem": "Which fibers cross at the optic chiasm?", "options": [{"text": "All optic nerve axons bilaterally", "why": "Only a subset crosses; temporal fibers remain on their original side."}, {"text": "All axons from the left eye only", "why": "Crossing depends on retinal half rather than eye alone."}, {"text": "Temporal retinal axons only", "why": "Temporal retinal fibers ordinarily remain ipsilateral."}, {"text": "Oculomotor efferent axons", "why": "CN III does not traverse the optic chiasm as the visual crossing population."}, {"text": "Nasal retinal ganglion-cell axons", "why": "Crossing nasal fibers join uncrossed temporal retinal fibers from the opposite eye to encode a shared contralateral hemifield."}], "answer": 4}, {"id": "Q144", "deck": "path", "ref": "slide-path-15", "page": 15, "topic": "Chiasm and optic tracts", "stem": "What visual information does the right optic tract carry?", "options": [{"text": "All temporal fields from both eyes", "why": "That would require both nasal retinal populations together, which is not a single tract's organization."}, {"text": "Left visual hemifield from both eyes", "why": "It contains crossed left nasal retinal fibers and uncrossed right temporal retinal fibers."}, {"text": "All visual information from the right eye", "why": "Each tract contains fibers from both eyes."}, {"text": "Right visual hemifield from both eyes", "why": "That travels in the left optic tract."}, {"text": "Only foveal information from the left eye", "why": "The tract encodes a hemifield, not just one eye's fovea."}], "answer": 1}, {"id": "Q145", "deck": "path", "ref": "slide-path-15", "page": 15, "topic": "Chiasm and optic tracts", "stem": "Which retinal fiber populations form the left optic tract?", "options": [{"text": "All retinal fibers from the left eye", "why": "Each optic tract has contributions from both eyes."}, {"text": "Both temporal populations", "why": "Temporal fibers remain on different sides."}, {"text": "Left nasal and right temporal retinal axons", "why": "These form the right optic tract and encode left visual space."}, {"text": "Right nasal and left temporal retinal axons", "why": "Both encode right visual space, with the nasal right-eye population crossing at chiasm."}, {"text": "Both nasal populations", "why": "These are the fibers crossing in opposite directions, not a single tract's full content."}], "answer": 3}, {"id": "Q146", "deck": "path", "ref": "slide-path-16", "page": 16, "topic": "Optic radiations", "stem": "Meyer's loop carries which information?", "options": [{"text": "Ipsilateral inferior field from superior retina", "why": "This has incorrect laterality and vertical mapping."}, {"text": "All monocular input from the ipsilateral eye", "why": "Postchiasmal pathways combine both eyes' information."}, {"text": "Corneal sensation to facial nuclei", "why": "That belongs to the blink reflex, not optic radiations."}, {"text": "Contralateral inferior field through superior retina", "why": "That travels chiefly in parietal radiations."}, {"text": "Contralateral superior visual field from inferior retina", "why": "Inferior retinal fibers loop through temporal lobe to inferior calcarine cortex; injury causes superior quadrantanopia."}], "answer": 4}, {"id": "Q147", "deck": "path", "ref": "slide-path-16", "page": 16, "topic": "Optic radiations", "stem": "Superior retinal fibers conveying the contralateral inferior visual field mainly course through which lobe?", "options": [{"text": "Frontal pole", "why": "This is not the principal geniculocalcarine route."}, {"text": "Medulla", "why": "This is not the cerebral optic radiation pathway."}, {"text": "Temporal lobe Meyer's loop", "why": "Meyer's loop mainly carries inferior retinal/superior field information."}, {"text": "Parietal lobe", "why": "The superior optic radiations travel parietally; their lesions cause inferior quadrantanopia."}, {"text": "Cerebellar hemisphere", "why": "This does not carry optic radiations to V1."}], "answer": 3}, {"id": "Q148", "deck": "path", "ref": "slide-path-16", "page": 16, "topic": "Optic radiations", "stem": "Which description of the LGN is correct?", "options": [{"text": "A ganglion in the orbit supplying the pupil", "why": "That is ciliary ganglion."}, {"text": "A facial motor nucleus producing eyelid closure", "why": "Facial nucleus is a pontine motor structure."}, {"text": "A thalamic relay receiving the contralateral visual hemifield and projecting to ipsilateral V1", "why": "Each LGN receives combined input from both eyes after chiasmal sorting and sends optic radiations to cortex on its own side."}, {"text": "A cortical gyrus representing only ipsilateral visual space", "why": "LGN is thalamic and represents contralateral space."}, {"text": "A midbrain nucleus that directly innervates sphincter pupillae", "why": "Parasympathetic output comes from Edinger–Westphal via ganglionic relay."}], "answer": 2}, {"id": "Q149", "deck": "path", "ref": "slide-path-17", "page": 17, "topic": "Visual cortex retinotopy", "stem": "Primary visual cortex lies principally along which sulcus?", "options": [{"text": "Central sulcus", "why": "This separates frontal and parietal primary motor/somatosensory territories."}, {"text": "Superior temporal sulcus", "why": "This is not the principal calcarine visual cortex site."}, {"text": "Lateral sulcus", "why": "This is not the primary visual cortical landmark."}, {"text": "Calcarine sulcus", "why": "V1/area 17 lies on the medial occipital surface around calcarine sulcus."}, {"text": "Cingulate sulcus", "why": "This is associated with medial limbic cortex rather than V1."}], "answer": 3}, {"id": "Q150", "deck": "path", "ref": "slide-path-17", "page": 17, "topic": "Visual cortex retinotopy", "stem": "A focal lesion of the left cuneus is expected to affect which visual quadrant?", "options": [{"text": "Left superior visual quadrant", "why": "This has both wrong laterality and bank association."}, {"text": "Right superior visual quadrant", "why": "This maps to inferior bank/lingual gyrus."}, {"text": "Entire left eye only", "why": "Cortical lesions generally cause homonymous rather than isolated monocular defects."}, {"text": "Right inferior visual quadrant", "why": "Superior bank/cuneus represents contralateral inferior visual field."}, {"text": "Left inferior visual quadrant", "why": "The left cortex processes right, not left, visual space."}], "answer": 3}, {"id": "Q151", "deck": "path", "ref": "slide-path-17", "page": 17, "topic": "Visual cortex retinotopy", "stem": "A lesion restricted to the right lingual gyrus most directly affects which region of visual space?", "options": [{"text": "Left inferior field", "why": "This maps to right cuneus/superior bank."}, {"text": "Only the right temporal monocular field with all else intact as the standard pattern", "why": "That is not the classic lingual-gyrus retinotopic deficit."}, {"text": "Right inferior field", "why": "This corresponds to the opposite hemisphere and bank."}, {"text": "Left superior field", "why": "Inferior calcarine bank/lingual gyrus represents contralateral superior field."}, {"text": "Right superior field", "why": "This maps to left inferior bank."}], "answer": 3}, {"id": "Q152", "deck": "path", "ref": "slide-path-17", "page": 17, "topic": "Visual cortex retinotopy", "stem": "Which cortical region represents central macular vision?", "options": [{"text": "Cerebellar vermis", "why": "This does not contain the primary conscious macular representation."}, {"text": "Occipital pole", "why": "Central vision is represented posteriorly with extensive cortical allocation; more anterior calcarine regions represent peripheral vision."}, {"text": "Most anterior calcarine cortex exclusively", "why": "This preferentially represents peripheral rather than central fields."}, {"text": "Precentral gyrus", "why": "This is primary motor cortex."}, {"text": "Medial geniculate body", "why": "This is an auditory relay, not occipital cortex."}], "answer": 1}, {"id": "Q153", "deck": "path", "ref": "slide-path-18", "page": 18, "topic": "Integrated visual localization", "stem": "A lesion interrupts inferior retinal fibers in the left temporal lobe. Which field deficit follows?", "options": [{"text": "Bitemporal hemianopia", "why": "This suggests crossing fibers at the chiasm."}, {"text": "Left monocular blindness", "why": "A temporal radiation lesion is postchiasmal and affects shared fields of both eyes."}, {"text": "Left superior homonymous quadrantanopia", "why": "Laterality is reversed; this would suggest right temporal injury."}, {"text": "Right superior homonymous quadrantanopia", "why": "Inferior retina represents upper space, and left postchiasmal pathways carry right space; temporal fibers are Meyer's loop."}, {"text": "Right inferior homonymous quadrantanopia", "why": "Inferior field is carried by superior retinal/parietal pathways."}], "answer": 3}, {"id": "Q154", "deck": "path", "ref": "slide-path-18", "page": 18, "topic": "Integrated visual localization", "stem": "Which rule is most useful when distinguishing retinal side from visual-field side in a lesion question?", "options": [{"text": "First invert the field onto retina, then apply nasal crossing and contralateral cerebral representation", "why": "This avoids mistaking temporal visual field for temporal retina and keeps eye side distinct from hemifield side."}, {"text": "Superior visual field always projects to superior retina", "why": "Optics invert the vertical image."}, {"text": "Temporal visual field always stays ipsilateral because temporal retina stays ipsilateral", "why": "Temporal visual field falls on nasal retina, which crosses."}, {"text": "The left cerebral hemisphere sees only through the left eye", "why": "Each hemisphere receives both eyes' contralateral hemifield information."}, {"text": "Every postchiasmal lesion causes monocular loss", "why": "Postchiasmal lesions classically cause homonymous deficits."}], "answer": 0}, {"id": "Q155", "deck": "path", "ref": "slide-path-20", "page": 20, "topic": "Visual field defects", "stem": "Loss of vision confined to one eye most strongly localizes where?", "options": [{"text": "Retina or optic nerve before the chiasm", "why": "Prechiasmal lesions affect one eye; exact pattern depends on lesion extent and site."}, {"text": "Both nasal crossing populations at chiasm", "why": "This classically causes bitemporal hemianopia."}, {"text": "Complete optic tract on the opposite side", "why": "A tract lesion typically produces a contralateral homonymous field deficit in both eyes."}, {"text": "One temporal optic radiation", "why": "This causes contralateral superior homonymous quadrantanopia."}, {"text": "One occipital hemisphere", "why": "This classically affects the same contralateral field in both eyes."}], "answer": 0}, {"id": "Q156", "deck": "path", "ref": "slide-path-20", "page": 20, "topic": "Visual field defects", "stem": "What does homonymous hemianopia mean?", "options": [{"text": "Loss of the same visual-space half in both eyes", "why": "This is a postchiasmal pattern; the affected hemifield is opposite the cerebral lesion."}, {"text": "Loss of the temporal half in both eyes", "why": "That is bitemporal heteronymous hemianopia."}, {"text": "Only loss of near accommodation", "why": "That concerns focus, not a hemifield deficit."}, {"text": "Failure of both pupils to constrict with normal fields", "why": "That is a pupillary reflex abnormality rather than a field definition."}, {"text": "Loss of all sight in only one eye", "why": "That is monocular blindness."}], "answer": 0}, {"id": "Q157", "deck": "path", "ref": "slide-path-21", "page": 21, "topic": "Optic nerve and chiasm lesions", "stem": "After traumatic transection of the right optic nerve, which visual deficit is expected?", "options": [{"text": "Left monocular blindness", "why": "This would follow left optic nerve transection."}, {"text": "Right superior homonymous quadrantanopia", "why": "This suggests left temporal radiation injury."}, {"text": "Left homonymous hemianopia", "why": "This suggests right postchiasmal pathway injury."}, {"text": "Right monocular blindness", "why": "The right optic nerve contains all afferent visual information from the right eye before chiasmal sorting."}, {"text": "Bitemporal hemianopia", "why": "This suggests central chiasmal damage."}], "answer": 3}, {"id": "Q158", "deck": "path", "ref": "slide-path-21", "page": 21, "topic": "Optic nerve and chiasm lesions", "stem": "A 42-year-old patient reports bumping into people approaching from either side. Over several months, reading straight ahead has remained relatively easy. Formal perimetry shows loss of the temporal half of each eye's visual field, and MRI reveals a sellar mass extending upward. Extraocular movements remain full. Which fiber population is most directly compressed by this mass?", "options": [{"text": "Right inferior retinal fibers in Meyer's loop", "why": "That would cause left superior homonymous quadrantanopia."}, {"text": "Macular cortex in the left occipital pole only", "why": "This would affect right central homonymous vision, not both temporal fields."}, {"text": "Crossing nasal retinal fibers at the optic chiasm", "why": "Each nasal hemiretina detects its temporal field, so midline chiasmal compression by a pituitary mass causes bitemporal hemianopia."}, {"text": "All left optic nerve fibers", "why": "That would produce left monocular loss rather than a heteronymous bilateral defect."}, {"text": "Uncrossed temporal retinal fibers in the right optic tract only", "why": "These alone cannot explain bilateral temporal field loss."}], "answer": 2}, {"id": "Q159", "deck": "path", "ref": "slide-path-21", "page": 21, "topic": "Optic nerve and chiasm lesions", "stem": "Why does central chiasmal compression produce temporal rather than nasal field loss?", "options": [{"text": "Temporal retinal fibers cross and detect temporal space", "why": "Temporal retinal fibers ordinarily remain ipsilateral and detect nasal space."}, {"text": "Each optic nerve contains only temporal field information", "why": "Each optic nerve carries the entire visual input from its eye."}, {"text": "The pituitary directly supplies both temporal retinal arteries", "why": "The classic deficit is neural fiber compression, not this proposed vascular supply."}, {"text": "The chiasm is part of the corneal blink pathway", "why": "The blink afferent route uses V1 and trigeminal circuitry."}, {"text": "Crossing fibers arise from nasal retina, which detects temporal visual space", "why": "Retinal location and visual-field location are opposite; this is the key step in the chiasm question."}], "answer": 4}, {"id": "Q160", "deck": "path", "ref": "slide-path-22", "page": 22, "topic": "Optic tract lesions", "stem": "A complete left optic tract lesion causes which deficit?", "options": [{"text": "Bitemporal hemianopia", "why": "This suggests midline chiasmal crossing-fiber injury."}, {"text": "Left monocular blindness", "why": "This suggests left prechiasmal injury."}, {"text": "Left homonymous hemianopia", "why": "This would follow right postchiasmal pathway injury."}, {"text": "Right homonymous hemianopia", "why": "The left tract carries right visual-space information from both eyes."}, {"text": "Binasal hemianopia as the usual complete-tract pattern", "why": "This is heteronymous and not the classic single-tract result."}], "answer": 3}, {"id": "Q161", "deck": "path", "ref": "slide-path-22", "page": 22, "topic": "Optic tract lesions", "stem": "A patient cannot see objects left of fixation with either eye. A lesion is identified in the right optic tract. Which retinal populations have lost their central connection?", "options": [{"text": "Left nasal and right temporal hemiretinae", "why": "These encode the left hemifield and join within the right tract after nasal crossing."}, {"text": "Both superior hemiretinae only", "why": "These would primarily encode inferior field information rather than an entire left hemifield."}, {"text": "All ganglion cells in the left eye only", "why": "This would produce left monocular loss rather than a binocular left hemifield deficit."}, {"text": "Left temporal and right nasal hemiretinae", "why": "These encode the right hemifield and join in the left tract."}, {"text": "Both inferior hemiretinae only", "why": "These encode superior fields rather than the complete left half."}], "answer": 0}, {"id": "Q162", "deck": "path", "ref": "slide-path-23", "page": 23, "topic": "Radiation lesions", "stem": "A patient undergoes left temporal lobe surgery and afterward misses objects in the upper right quadrant with either eye. Which structure was most likely damaged?", "options": [{"text": "Central optic chiasm", "why": "This produces bitemporal rather than homonymous quadrant loss."}, {"text": "Left parietal optic radiations", "why": "These carry right inferior field information."}, {"text": "Right optic nerve", "why": "This would cause right monocular visual loss."}, {"text": "Left Meyer's loop", "why": "Left temporal inferior retinal fibers carry right superior visual-space information, producing 'pie in the sky' loss."}, {"text": "Right Meyer's loop", "why": "This would cause left superior quadrantanopia."}], "answer": 3}, {"id": "Q163", "deck": "path", "ref": "slide-path-23", "page": 23, "topic": "Radiation lesions", "stem": "A right parietal lesion interrupts superior optic radiations. What field defect is most likely?", "options": [{"text": "Right inferior homonymous quadrantanopia", "why": "This would localize to left parietal radiations."}, {"text": "Bitemporal hemianopia", "why": "This localizes to chiasmal crossing fibers."}, {"text": "Left inferior homonymous quadrantanopia", "why": "Right parietal superior retinal fibers encode left inferior space: 'pie on the floor.'"}, {"text": "Right monocular blindness", "why": "A right optic nerve lesion causes that pattern."}, {"text": "Left superior homonymous quadrantanopia", "why": "This is a right temporal/Meyer's loop pattern."}], "answer": 2}, {"id": "Q164", "deck": "path", "ref": "slide-path-23", "page": 23, "topic": "Radiation lesions", "stem": "Which pair correctly links radiation anatomy to field loss?", "options": [{"text": "Both lesions always eliminate every visual field bilaterally", "why": "Focal unilateral radiation lesions cause restricted contralateral homonymous defects."}, {"text": "Both lesions always affect only the ipsilateral eye", "why": "Radiations carry binocular hemifield information."}, {"text": "Temporal lesion: monocular blindness; parietal lesion: bitemporal loss", "why": "These are prechiasmal and chiasmal rather than radiation patterns."}, {"text": "Temporal lesion: ipsilateral inferior; parietal lesion: ipsilateral superior", "why": "Both laterality and vertical assignments are wrong."}, {"text": "Temporal lesion: contralateral superior quadrant; parietal lesion: contralateral inferior quadrant", "why": "These patterns follow retinal inversion and ipsilateral radiation projections from LGN to V1."}], "answer": 4}, {"id": "Q165", "deck": "path", "ref": "slide-path-24", "page": 24, "topic": "Cortical visual lesions", "stem": "A 71-year-old patient suddenly notices missing vision to the left while eating breakfast. Examination shows left homonymous hemianopia with preserved central fixation in both eyes. Strength and speech are normal. Both pupils react briskly to light. MRI shows an acute medial right occipital infarct, while the occipital pole is relatively spared. Which vessel is most classically associated with this lesion?", "options": [{"text": "Left anterior cerebral artery", "why": "Its territory and side do not match this visual lesion."}, {"text": "Right anterior cerebral artery", "why": "This mainly supplies medial frontal/parietal cortex, not the classic calcarine territory."}, {"text": "Right external carotid artery as the direct calcarine artery", "why": "External carotid is not the classic primary supply to medial occipital cortex."}, {"text": "Left posterior cerebral artery", "why": "This would more likely cause right homonymous visual loss."}, {"text": "Right posterior cerebral artery", "why": "PCA supplies much medial occipital visual cortex; sparing of macular cortex can preserve central vision, and the light reflex can remain intact because it uses pretectal pathways."}], "answer": 4}, {"id": "Q166", "deck": "path", "ref": "slide-path-24", "page": 24, "topic": "Cortical visual lesions", "stem": "What is the best interpretation of macular sparing in a homonymous hemianopia?", "options": [{"text": "It guarantees a lesion in the ciliary ganglion", "why": "Ciliary ganglion lesions affect pupil/accommodation rather than homonymous fields."}, {"text": "The optic disc acquires photoreceptors", "why": "Macular sparing is cortical/field preservation, not a change in disc anatomy."}, {"text": "Central vision is preserved despite loss of much of the same hemifield in both eyes", "why": "This often supports occipital involvement with spared macular cortex, sometimes due to collateral supply, but is not obligatory or absolutely site-specific."}, {"text": "Only the temporal field of one eye is preserved", "why": "Macular refers to central fixation, not a single temporal peripheral field."}, {"text": "It rules out every occipital lesion", "why": "Macular sparing is classically associated with some occipital lesions."}], "answer": 2}, {"id": "Q167", "deck": "path", "ref": "slide-path-24", "page": 24, "topic": "Cortical visual lesions", "stem": "A focal lesion destroys the left occipital pole but spares more anterior calcarine cortex. Which visual function is most directly threatened?", "options": [{"text": "Only corneal touch in the right eye", "why": "That depends on V1 afferents."}, {"text": "Only pupil dilation in the left eye", "why": "That depends on sympathetic ocular pathways."}, {"text": "Right central homonymous vision", "why": "Posterior occipital cortex represents the macular field; more anterior regions represent peripheral visual space."}, {"text": "Only lens refraction in both eyes", "why": "Cortical macular destruction affects perception rather than intrinsic lens optics."}, {"text": "Only left monocular vision", "why": "A unilateral cortical lesion affects contralateral visual space in both eyes."}], "answer": 2}, {"id": "Q168", "deck": "path", "ref": "slide-path-25", "page": 25, "topic": "Integrated visual localization", "stem": "Which lesion–deficit pair is correctly matched?", "options": [{"text": "Right optic tract — right homonymous hemianopia", "why": "Right tract injury causes left homonymous hemianopia."}, {"text": "Right Meyer's loop — right superior quadrantanopia", "why": "Right temporal injury causes left superior quadrantanopia."}, {"text": "Left optic nerve — right monocular blindness", "why": "Left optic nerve injury affects the left eye."}, {"text": "Left parietal radiations — right inferior quadrantanopia", "why": "Parietal radiations carry contralateral inferior field information."}, {"text": "Central optic chiasm — left homonymous hemianopia", "why": "Central chiasmal injury classically causes bitemporal loss."}], "answer": 3}, {"id": "Q169", "deck": "path", "ref": "slide-path-25", "page": 25, "topic": "Integrated visual localization", "stem": "Perimetry shows loss of the right half of the visual field in both eyes. Which proposed site is incompatible with a single lesion producing this classic pattern?", "options": [{"text": "Extensive left optic radiations", "why": "These project right hemifield information to cortex."}, {"text": "Left lateral geniculate nucleus", "why": "This relays right hemifield information."}, {"text": "Left primary visual cortex", "why": "This represents right visual space."}, {"text": "Right optic nerve alone", "why": "This affects input from only the right eye. Left tract, LGN, radiations, or V1 can produce right homonymous loss."}, {"text": "Left optic tract", "why": "This carries right hemifield information from both eyes."}], "answer": 3}, {"id": "Q170", "deck": "path", "ref": "slide-path-25", "page": 25, "topic": "Integrated visual localization", "stem": "An examiner notes that the patient repeatedly confuses 'right eye blindness' with 'right visual field loss.' Which observation establishes a homonymous defect?", "options": [{"text": "Only near focusing is blurred", "why": "That is an optical accommodation problem rather than proof of field loss."}, {"text": "Both temporal halves are absent", "why": "That is bitemporal heteronymous loss."}, {"text": "The same right half is absent when either eye is tested separately", "why": "Testing each eye demonstrates a binocular hemifield deficit, supporting left postchiasmal localization."}, {"text": "The entire right eye is blind with a normal left eye", "why": "That is a monocular prechiasmal pattern."}, {"text": "Only one eyelid cannot close", "why": "That is an eyelid motor problem, not a homonymous field definition."}], "answer": 2}, {"id": "Q171", "deck": "reflex", "ref": "slide-reflex-2", "page": 2, "topic": "Pupillary light reflex", "stem": "Which nerve carries the afferent limb of the pupillary light reflex?", "options": [{"text": "CN V1", "why": "V1 carries corneal touch afference rather than retinal light input."}, {"text": "CN III", "why": "III carries the parasympathetic efferent limb."}, {"text": "CN VIII", "why": "VIII carries vestibular/auditory input rather than pupillary light afference."}, {"text": "CN II", "why": "Retinal ganglion axons carry the light signal through optic nerve pathways toward pretectal nuclei."}, {"text": "CN VII", "why": "VII closes eyelids through orbicularis oculi."}], "answer": 3}, {"id": "Q172", "deck": "reflex", "ref": "slide-reflex-2", "page": 2, "topic": "Pupillary light reflex", "stem": "Why does light directed into one normal eye constrict both pupils?", "options": [{"text": "All retinal axons cross at the chiasm", "why": "Temporal retinal fibers remain ipsilateral, and complete crossing is not the mechanism."}, {"text": "CN II is the motor nerve to both sphincters", "why": "II is sensory, not the pupillary motor output."}, {"text": "Each ciliary ganglion sends all fibers to both eyes", "why": "The relevant output is principally ipsilateral; bilaterality arises centrally."}, {"text": "Pretectal projections activate both Edinger–Westphal nuclei", "why": "Bilateral central connections distribute one eye's light signal to both parasympathetic outputs, producing direct and consensual responses."}, {"text": "The two iris sphincters are physically joined", "why": "They are separate muscles; coordination is neural."}], "answer": 3}, {"id": "Q173", "deck": "reflex", "ref": "slide-reflex-2", "page": 2, "topic": "Pupillary light reflex", "stem": "Which structure contains preganglionic parasympathetic neurons for pupillary constriction?", "options": [{"text": "Lateral geniculate nucleus", "why": "This is the principal thalamic visual relay."}, {"text": "Superior cervical ganglion", "why": "This contains postganglionic sympathetic neurons for dilation."}, {"text": "Edinger–Westphal nucleus", "why": "Its axons run with III and synapse in ciliary ganglion before reaching sphincter pupillae."}, {"text": "Spinal trigeminal nucleus", "why": "This processes somatic sensation including the corneal reflex afferent input."}, {"text": "Facial motor nucleus", "why": "This supplies facial muscles including orbicularis oculi."}], "answer": 2}, {"id": "Q174", "deck": "reflex", "ref": "slide-reflex-2", "page": 2, "topic": "Pupillary light reflex", "stem": "Where do preganglionic ocular parasympathetic fibers synapse before traveling in short ciliary nerves?", "options": [{"text": "Dorsal root ganglion", "why": "This houses somatic sensory neurons rather than this ocular parasympathetic synapse."}, {"text": "LGN", "why": "This is a thalamic sensory relay rather than peripheral parasympathetic ganglion."}, {"text": "Ciliary ganglion", "why": "This orbital parasympathetic ganglion relays output to sphincter pupillae and ciliary muscle."}, {"text": "Otic ganglion", "why": "This relays parasympathetic supply to parotid gland."}, {"text": "Superior cervical ganglion", "why": "This is the sympathetic ganglion for ocular dilation pathways."}], "answer": 2}, {"id": "Q175", "deck": "reflex", "ref": "slide-reflex-2", "page": 2, "topic": "Pupillary light reflex", "stem": "Light in the left eye causes the right pupil to constrict. What is this response called?", "options": [{"text": "Vestibulo-ocular reflex", "why": "This couples eye movement to head movement."}, {"text": "Convergence", "why": "This is inward movement of both eyes for near fixation."}, {"text": "Consensual pupillary light response", "why": "The contralateral pupil constricts through bilateral pretectal–Edinger–Westphal connections."}, {"text": "Direct response of the right pupil", "why": "A right direct response requires light in the right eye."}, {"text": "Corneal blink reflex", "why": "This requires corneal touch and eyelid closure."}], "answer": 2}, {"id": "Q176", "deck": "reflex", "ref": "slide-reflex-3", "page": 3, "topic": "Pupillary lesion localization", "stem": "Light in the left eye produces no constriction of either pupil. Light in the right eye constricts both pupils normally. Assuming a complete isolated nerve lesion, where is the lesion?", "options": [{"text": "Bilateral ciliary ganglia", "why": "Both pupils would fail to constrict even when right-eye afference is intact."}, {"text": "Right oculomotor parasympathetic fibers", "why": "The right pupil would fail to constrict to either stimulus."}, {"text": "Right optic nerve", "why": "This would eliminate bilateral responses to right-eye rather than left-eye light."}, {"text": "Left optic nerve", "why": "Left afferent input is absent, but both efferent pathways work when the right retina is stimulated."}, {"text": "Left oculomotor parasympathetic fibers", "why": "This would prevent left constriction regardless of which eye is illuminated."}], "answer": 3}, {"id": "Q177", "deck": "reflex", "ref": "slide-reflex-3", "page": 3, "topic": "Pupillary lesion localization", "stem": "Regardless of which eye receives light, the right pupil constricts and the left pupil does not. Visual acuity is normal in both eyes. Which lesion best fits?", "options": [{"text": "Left parasympathetic efferent pathway carried by CN III", "why": "An efferent defect prevents the affected pupil from responding to either eye's afferent stimulus; isolated parasympathetic injury may spare other III functions."}, {"text": "Left optic nerve", "why": "A complete left afferent lesion would eliminate both responses to left light, yet preserve both with right light."}, {"text": "Left V1", "why": "This affects corneal touch afference rather than pupillary light input."}, {"text": "Right facial nerve", "why": "This affects right eyelid closure rather than left pupil constriction."}, {"text": "Right optic nerve", "why": "This would impair input from the right eye, not selectively disable left output."}], "answer": 0}, {"id": "Q178", "deck": "reflex", "ref": "slide-reflex-3", "page": 3, "topic": "Pupillary lesion localization", "stem": "A complete right optic nerve lesion is present, and both pupillary efferent limbs are intact. What happens when light is shone in the left eye?", "options": [{"text": "Both pupils constrict", "why": "Normal left afference activates bilateral outputs, including a consensual response in the blind right eye."}, {"text": "Only the right pupil constricts", "why": "The left direct response should also be intact."}, {"text": "Neither pupil constricts", "why": "This would require absent left afference or bilateral output failure."}, {"text": "Only the left pupil constricts because the right eye is blind", "why": "Blindness from afferent loss does not itself disable the right efferent sphincter pathway."}, {"text": "The right eye abducts as the pupillary response", "why": "Abduction is an extraocular movement, not the light-reflex response."}], "answer": 0}, {"id": "Q179", "deck": "reflex", "ref": "slide-reflex-3", "page": 3, "topic": "Pupillary lesion localization", "stem": "A complete right CN III lesion includes its parasympathetic fibers. CN II is intact bilaterally. What occurs when light is shone in the right eye?", "options": [{"text": "Left pupil constricts; right pupil does not", "why": "Right retinal afference still reaches bilateral central nuclei, but only the intact left output can constrict its pupil."}, {"text": "Right pupil constricts; left does not", "why": "This reverses the affected efferent side."}, {"text": "Both pupils develop a relative afferent defect", "why": "A III lesion is efferent, not afferent."}, {"text": "Neither pupil constricts", "why": "That would imply absent afferent input or bilateral efferent failure."}, {"text": "Both pupils constrict normally", "why": "The right efferent pathway is interrupted."}], "answer": 0}, {"id": "Q180", "deck": "reflex", "ref": "slide-reflex-3", "page": 3, "topic": "Pupillary lesion localization", "stem": "A 60-year-old patient develops acute left ptosis and diplopia. The left eye rests down and out and its pupil is large. When light is directed into the left eye, the right pupil constricts briskly but the left does not. The same pupil pattern occurs when the right eye is illuminated. Which explanation best unifies the ocular motor and pupil findings?", "options": [{"text": "Right MLF lesion", "why": "This causes right adduction weakness during horizontal gaze, not this complete left III pattern."}, {"text": "Left facial nerve palsy", "why": "This weakens eyelid closure rather than levator function and pupil constriction."}, {"text": "Left optic nerve transection alone", "why": "This would impair left visual input but would not cause III-pattern ophthalmoplegia or abolish left consensual response to right light."}, {"text": "Right CN VI lesion", "why": "This affects right abduction, not the left pupil and levator."}, {"text": "Left CN III lesion including somatic and parasympathetic fibers", "why": "Loss of III motor supply produces ptosis/down-and-out position, while efferent parasympathetic failure prevents left miosis with either afferent stimulus."}], "answer": 4}, {"id": "Q181", "deck": "reflex", "ref": "slide-reflex-3", "page": 3, "topic": "Pupillary lesion localization", "stem": "A painful new third-nerve palsy includes a dilated poorly reactive pupil. Which vascular lesion is a classic compressive cause to consider in this high-yield localization pattern?", "options": [{"text": "Posterior communicating artery aneurysm", "why": "A compressive aneurysm can affect superficial III parasympathetic fibers; pupil findings are useful but do not by themselves exclude serious causes in pupil-sparing presentations."}, {"text": "External carotid stenosis as the classic III compression site", "why": "This is not the characteristic intracranial aneurysm association."}, {"text": "Ductus arteriosus persistence", "why": "This is not the classic cause of an acute III palsy."}, {"text": "Occlusion of a superficial scalp vein", "why": "This does not explain the characteristic compressive III syndrome."}, {"text": "Anterior spinal artery occlusion at the lumbar cord", "why": "This does not compress III near the midbrain."}], "answer": 0}, {"id": "Q182", "deck": "reflex", "ref": "slide-reflex-4", "page": 4, "topic": "Relative afferent defect", "stem": "During a swinging flashlight test, both pupils constrict with right-eye illumination and then relatively dilate when the light is moved to the left eye. What does this imply?", "options": [{"text": "Left relative afferent pupillary defect", "why": "The left eye supplies less afferent light input; both intact efferent outputs relax relative to the response driven by the healthier eye."}, {"text": "Right RAPD", "why": "Moving from the healthy eye to the affected eye produces relative dilation, so the affected side here is left."}, {"text": "Bilateral orbicularis oculi paralysis", "why": "Blink motor function is different from the pupil response."}, {"text": "Normal equal afferent function", "why": "Equal retinal/optic nerve input would not produce this consistent asymmetric response."}, {"text": "Left isolated CN III palsy", "why": "An efferent lesion would selectively impair left constriction with either stimulus."}], "answer": 0}, {"id": "Q183", "deck": "reflex", "ref": "slide-reflex-4", "page": 4, "topic": "Relative afferent defect", "stem": "A 25-year-old patient has pain on left eye movement and subacute monocular visual blur with reduced color saturation. The pupils are equal in size at rest, and extraocular movements are full. When the examiner swings a light from right to left, both pupils dilate relatively, then constrict more strongly when it returns to the right. Which process most likely explains this examination?", "options": [{"text": "Left optic neuropathy producing an RAPD", "why": "Optic neuritis is a classic cause of reduced afferent input; normal resting pupil size and intact III function are compatible with RAPD."}, {"text": "Right facial palsy", "why": "This affects right eyelid closure, not light afference."}, {"text": "Isolated left lens accommodation failure", "why": "This does not explain the swinging-light asymmetry from reduced retinal/optic nerve input."}, {"text": "Complete left III palsy", "why": "This would cause an efferent abnormality, often with ocular motor findings, rather than bilateral relative dilation driven by left input."}, {"text": "Right MLF lesion", "why": "This causes right adduction impairment during horizontal gaze rather than this sensory defect."}], "answer": 0}, {"id": "Q184", "deck": "reflex", "ref": "slide-reflex-4", "page": 4, "topic": "Relative afferent defect", "stem": "Which statement correctly distinguishes an RAPD from a complete optic nerve lesion?", "options": [{"text": "An RAPD proves a ciliary ganglion lesion", "why": "Ciliary ganglion damage is efferent."}, {"text": "An RAPD is assessed by touching the cornea only", "why": "It is evaluated using the swinging flashlight test."}, {"text": "An RAPD reflects asymmetric afferent input and need not abolish all light responses", "why": "The deck's complete CN II table is an idealized extreme; partial optic nerve disease can still drive weaker bilateral constriction."}, {"text": "An RAPD always means the affected pupil cannot constrict to either eye", "why": "That describes efferent failure, not afferent asymmetry."}, {"text": "An RAPD requires unequal pupil diameters at rest", "why": "Pupils can be equal when efferent pathways are intact."}], "answer": 2}, {"id": "Q185", "deck": "reflex", "ref": "slide-reflex-5", "page": 5, "topic": "Near response", "stem": "Which three changes constitute the near response?", "options": [{"text": "Accommodation, convergence, and miosis", "why": "The lens rounds, medial recti turn both eyes inward, and sphincter pupillae constricts the pupils."}, {"text": "Nystagmus, ptosis, and blindness", "why": "These are pathological findings rather than the normal triad."}, {"text": "Pupil dilation, superior oblique contraction, and lens opacity", "why": "These are not normal near response components."}, {"text": "Lens flattening, divergence, and mydriasis", "why": "These oppose the normal near triad."}, {"text": "Blinking, tearing, and abduction", "why": "These are not the accommodation-convergence triad."}], "answer": 0}, {"id": "Q186", "deck": "reflex", "ref": "slide-reflex-5", "page": 5, "topic": "Near response", "stem": "Which extraocular muscles mediate normal convergence?", "options": [{"text": "Both levator palpebrae muscles", "why": "These elevate eyelids rather than turn eyes inward."}, {"text": "Both medial rectus muscles", "why": "Bilateral III somatic motor output adducts both eyes toward a near target."}, {"text": "Both superior oblique muscles", "why": "These principally intort/depress the eyes rather than mediate convergence."}, {"text": "Both lateral rectus muscles", "why": "These abduct the eyes and favor divergence."}, {"text": "Both orbicularis oculi muscles", "why": "These close eyelids through VII."}], "answer": 1}, {"id": "Q187", "deck": "reflex", "ref": "slide-reflex-5", "page": 5, "topic": "Near response", "stem": "Why does pupil constriction assist near vision?", "options": [{"text": "A smaller aperture increases depth of focus and reduces peripheral optical aberration", "why": "Miosis complements increased lens power and convergence; it is not the mechanism that changes lens curvature."}, {"text": "It causes the optic disc to transduce light", "why": "The disc remains without photoreceptors."}, {"text": "It turns nasal retinal fibers into temporal fibers", "why": "Pupil diameter does not change retinal axon identities."}, {"text": "It tightens zonules to flatten the lens for near focus", "why": "Near accommodation instead relaxes zonules and rounds the lens."}, {"text": "It replaces all need for lens accommodation", "why": "Near focus still requires an appropriate optical focal plane."}], "answer": 0}, {"id": "Q188", "deck": "reflex", "ref": "slide-reflex-6", "page": 6, "topic": "Near response pathways", "stem": "Which distinction between light and near pathways is most accurate?", "options": [{"text": "The light reflex requires facial nerve motor output", "why": "Its pupil efferent limb is III, not VII."}, {"text": "Both must pass through V1 cortex before any pupil response", "why": "The light reflex can remain with cortical blindness."}, {"text": "The near response has no afferent visual component", "why": "The deck describes retinal/CN II/cortical input."}, {"text": "Near fixation uses visual cortex/supranuclear pathways; the basic light reflex uses pretectal circuitry", "why": "Both ultimately use III parasympathetic output for miosis, but their upstream circuitry differs."}, {"text": "Near accommodation requires sympathetic superior cervical output exclusively", "why": "Accommodation uses ocular parasympathetic III pathways."}], "answer": 3}, {"id": "Q189", "deck": "reflex", "ref": "slide-reflex-6", "page": 6, "topic": "Near response pathways", "stem": "Which efferent functional categories does CN III supply during the near response?", "options": [{"text": "GVE to dilator through superior cervical ganglion only", "why": "The principal dilator pathway is sympathetic and does not describe III's near output."}, {"text": "SSA to vestibular nuclei and GSE to lateral rectus", "why": "These are VIII/VI roles in vestibular ocular circuitry."}, {"text": "GVE to ciliary muscle/sphincter and GSE to medial rectus", "why": "Parasympathetic visceral motor output produces accommodation/miosis; somatic motor output produces convergence."}, {"text": "GSA to cornea and SVE to orbicularis oculi", "why": "These are V1/VII roles in the corneal reflex."}, {"text": "Only sensory fibers from retina", "why": "CN III is motor/parasympathetic rather than the retinal afferent nerve."}], "answer": 2}, {"id": "Q190", "deck": "reflex", "ref": "slide-reflex-6", "page": 6, "topic": "Near response pathways", "stem": "Which nucleus supplies the somatic motor output for convergence, rather than the parasympathetic output for miosis?", "options": [{"text": "Spinal trigeminal nucleus", "why": "This processes corneal somatic sensory input."}, {"text": "Oculomotor motor nucleus", "why": "Its medial rectus neurons drive convergence; Edinger–Westphal supplies preganglionic parasympathetic pupil/lens output."}, {"text": "Pretectal nucleus", "why": "This is an upstream pupillary light-reflex relay."}, {"text": "Edinger–Westphal nucleus", "why": "This supplies the visceral parasympathetic component, not medial rectus somatic motor neurons."}, {"text": "Superior cervical ganglion", "why": "This is peripheral sympathetic output, not the III somatic motor nucleus."}], "answer": 1}, {"id": "Q191", "deck": "reflex", "ref": "slide-reflex-7", "page": 7, "topic": "Light-near dissociation", "stem": "Pupils constrict much better to near fixation than to bright light. What is this finding called?", "options": [{"text": "Light-near dissociation", "why": "The near response is preserved or relatively better despite impaired light-mediated constriction."}, {"text": "Relative afferent pupillary defect as the definition", "why": "RAPD is an inter-eye difference in afferent drive on swinging-light testing, not the definition of near-light disparity."}, {"text": "Physiological blind spot", "why": "This is the field location corresponding to the optic disc."}, {"text": "Homonymous hemianopia", "why": "This is a binocular visual-field deficit."}, {"text": "Internuclear ophthalmoplegia", "why": "This is a conjugate gaze coordination deficit."}], "answer": 0}, {"id": "Q192", "deck": "reflex", "ref": "slide-reflex-7", "page": 7, "topic": "Light-near dissociation", "stem": "A patient with neurosyphilis has small irregular pupils that react poorly to light but constrict on near fixation. What is the classic pupil finding?", "options": [{"text": "RAPD in one eye as the defining finding", "why": "RAPD is detected by asymmetric afferent drive, not this bilateral small irregular pupil pattern."}, {"text": "Argyll Robertson pupils", "why": "Small irregular pupils with light-near dissociation are the classic association emphasized by the slides."}, {"text": "Adie tonic pupil", "why": "Adie typically features a larger pupil with slow sustained near constriction."}, {"text": "Horner syndrome as the defining diagnosis", "why": "Horner causes miosis/ptosis from sympathetic loss, usually with preserved light constriction."}, {"text": "Complete III palsy", "why": "A complete efferent pupil lesion impairs both light and near constriction and may accompany ophthalmoplegia."}], "answer": 1}, {"id": "Q193", "deck": "reflex", "ref": "slide-reflex-7", "page": 7, "topic": "Light-near dissociation", "stem": "A young adult has a large pupil that reacts poorly to light but slowly constricts with prolonged near effort and redilates slowly. Which lesion is most characteristic?", "options": [{"text": "Sympathetic denervation of dilator pupillae", "why": "This typically produces a small pupil rather than a tonic large pupil."}, {"text": "Parietal radiation lesion alone", "why": "This produces a contralateral inferior field deficit, not a tonic pupil."}, {"text": "Facial motor nucleus destruction", "why": "This causes eyelid/facial weakness rather than iris parasympathetic dysfunction."}, {"text": "Complete optic nerve transection", "why": "This causes severe afferent visual loss, not the classic tonic near response."}, {"text": "Postganglionic parasympathetic dysfunction in Adie tonic pupil", "why": "Ciliary ganglion/short ciliary injury and aberrant reinnervation can produce tonic near responses; early near function may also be impaired."}], "answer": 4}, {"id": "Q194", "deck": "reflex", "ref": "slide-reflex-7", "page": 7, "topic": "Light-near dissociation", "stem": "A patient with a pineal-region mass has impaired upgaze, convergence-retraction nystagmus, and light-near dissociation. Which location best explains the syndrome?", "options": [{"text": "Right optic nerve alone", "why": "This causes a monocular afferent deficit rather than a dorsal midbrain gaze syndrome."}, {"text": "Dorsal midbrain", "why": "Parinaud syndrome involves dorsal midbrain structures, including pupillary light pathways, and is classically associated with pineal-region compression."}, {"text": "Ciliary muscle alone", "why": "A local muscle lesion does not explain supranuclear vertical gaze findings."}, {"text": "Facial nerve at the stylomastoid foramen", "why": "This affects facial muscles rather than vertical gaze and pupil light circuitry."}, {"text": "Lateral medulla", "why": "This produces a different crossed sensory/bulbar syndrome."}], "answer": 1}, {"id": "Q195", "deck": "reflex", "ref": "slide-reflex-7", "page": 7, "topic": "Light-near dissociation", "stem": "Why can near miosis remain better than light miosis in a dorsal midbrain lesion?", "options": [{"text": "Upstream light and near circuitry differ before converging on ocular parasympathetic output", "why": "Damage can preferentially affect light-reflex relays while relatively sparing supranuclear near pathways."}, {"text": "The near response normally dilates the pupil", "why": "Near response includes miosis."}, {"text": "Near miosis uses facial nerve instead of III", "why": "Both pupil constriction responses ultimately require III-related parasympathetic output."}, {"text": "Near miosis requires no sphincter pupillae function", "why": "The sphincter is the final pupil constrictor."}, {"text": "The optic disc creates a new motor pathway", "why": "The optic disc carries retinal ganglion axons, not an alternative efferent system."}], "answer": 0}, {"id": "Q196", "deck": "reflex", "ref": "slide-reflex-8", "page": 8, "topic": "Corneal reflex", "stem": "Which afferent route mediates corneal touch-evoked blinking?", "options": [{"text": "CN II to pretectal nuclei", "why": "This is the light-reflex afferent route."}, {"text": "Nasociliary branch of V1 to trigeminal sensory circuitry including spinal trigeminal nucleus", "why": "Corneal somatic sensory input activates bilateral facial motor output."}, {"text": "CN VIII to vestibular nuclei", "why": "This detects vestibular motion rather than corneal touch."}, {"text": "CN III to ciliary ganglion", "why": "This is parasympathetic output for pupil/lens functions."}, {"text": "CN IX to stylopharyngeus", "why": "This is not the corneal afferent pathway."}], "answer": 1}, {"id": "Q197", "deck": "reflex", "ref": "slide-reflex-8", "page": 8, "topic": "Corneal reflex", "stem": "Which muscle and nerve form the corneal blink reflex efferent limb?", "options": [{"text": "Levator palpebrae through CN III", "why": "Levator opens the eyelid rather than closes it."}, {"text": "Ciliary muscle through CN III", "why": "This adjusts lens curvature rather than blinking."}, {"text": "Orbicularis oculi through CN VII", "why": "Bilateral facial motor nuclei activate eyelid closure; the branchial motor category is SVE."}, {"text": "Sphincter pupillae through short ciliary nerves", "why": "This constricts the pupil rather than closes eyelids."}, {"text": "Lateral rectus through CN VI", "why": "This abducts the eye."}], "answer": 2}, {"id": "Q198", "deck": "reflex", "ref": "slide-reflex-8", "page": 8, "topic": "Corneal reflex", "stem": "Touching one normal cornea closes both eyelids. What central organization explains this?", "options": [{"text": "All facial motor fibers cross to the opposite eye only", "why": "Ipsilateral facial output supplies its own eyelid; bilateral activation occurs centrally."}, {"text": "Optic chiasm is the mandatory touch relay", "why": "The corneal reflex does not use the optic chiasm as its afferent relay."}, {"text": "Trigeminal sensory connections to both facial motor nuclei", "why": "One afferent corneal signal drives direct and consensual blink responses through bilateral motor connections."}, {"text": "Ciliary ganglion sends motor fibers to orbicularis", "why": "Orbicularis is supplied by VII rather than ocular parasympathetic ganglion."}, {"text": "A single orbicularis muscle shared by both eyes", "why": "Each eye has its own muscle; bilateral activation is neural."}], "answer": 2}, {"id": "Q199", "deck": "reflex", "ref": "slide-reflex-9", "page": 9, "topic": "Corneal lesion localization", "stem": "Touching the left cornea produces no blink in either eye. Touching the right cornea produces bilateral blinking. Which lesion is most likely?", "options": [{"text": "Left VII lesion", "why": "The left eyelid would fail to close regardless of which cornea is touched."}, {"text": "Bilateral VII lesions", "why": "Neither stimulus would produce bilateral blinking."}, {"text": "Right V1 lesion", "why": "This would eliminate the response to right-sided touch."}, {"text": "Left V1 afferent lesion", "why": "Left sensory input is absent, but both VII outputs are demonstrably intact when right corneal input is provided."}, {"text": "Right VII lesion", "why": "The right eyelid would fail with either stimulus."}], "answer": 3}, {"id": "Q200", "deck": "reflex", "ref": "slide-reflex-9", "page": 9, "topic": "Corneal lesion localization", "stem": "The right eyelid fails to close regardless of which cornea is touched; the left eyelid closes with either stimulus. Which nerve is most likely impaired?", "options": [{"text": "Right V1", "why": "A right afferent lesion would abolish both blinks on touching the right cornea, but preserve both with left touch."}, {"text": "Left CN III", "why": "III is not the orbicularis oculi motor nerve."}, {"text": "Right CN II", "why": "II mediates vision/light afference, not blink efference."}, {"text": "Right CN VII", "why": "The right efferent limb is defective, while sensory input from both corneas reaches the intact left motor output."}, {"text": "Left V1", "why": "This would impair input from the left rather than selectively right eyelid output."}], "answer": 3}, {"id": "Q201", "deck": "reflex", "ref": "slide-reflex-9", "page": 9, "topic": "Corneal lesion localization", "stem": "A complete left facial nerve lesion is present with intact bilateral V1 sensation. What happens when the left cornea is touched?", "options": [{"text": "Only the left eye blinks", "why": "This reverses the efferent lesion side."}, {"text": "Both eyes blink normally", "why": "Left output is interrupted."}, {"text": "Neither eye blinks", "why": "That would fit absent left afference rather than isolated left VII failure."}, {"text": "Right eyelid closes; left eyelid does not", "why": "The sensory signal reaches both motor nuclei, but left facial output cannot activate orbicularis."}, {"text": "Both pupils dilate as the defining response", "why": "Pupil dilation is not the corneal blink endpoint."}], "answer": 3}, {"id": "Q202", "deck": "reflex", "ref": "slide-reflex-9", "page": 9, "topic": "Corneal lesion localization", "stem": "A patient has left facial weakness including forehead involvement and cannot close the left eyelid. Both corneas are sensitive to touch. Which additional test pattern is expected?", "options": [{"text": "Right eyelid never closes, left closes normally", "why": "This suggests right rather than left facial efferent dysfunction."}, {"text": "Only near convergence is absent", "why": "This concerns III/near circuitry rather than facial motor blink output."}, {"text": "Left eyelid remains open with stimulation of either cornea", "why": "Peripheral VII dysfunction impairs ipsilateral blink output; preserved sensation distinguishes it from isolated V1 loss."}, {"text": "Both pupils fail to constrict only with left-eye illumination", "why": "That is a complete left CN II afferent pattern."}, {"text": "Neither eye blinks only when left cornea is touched", "why": "That is a left V1 afferent pattern."}], "answer": 2}, {"id": "Q203", "deck": "reflex", "ref": "slide-reflex-10", "page": 10, "topic": "Vestibulo-ocular reflex", "stem": "Which sensory structures and nerve initiate the angular vestibulo-ocular reflex?", "options": [{"text": "Retinal cones and CN II as an obligatory first step", "why": "VOR does not require conscious visual processing or retinal image detection as its initiating signal."}, {"text": "Cochlear hair cells and auditory VIII division only", "why": "Cochlea detects sound, not angular head rotation."}, {"text": "Corneal nociceptors and V1", "why": "These initiate protective corneal responses."}, {"text": "Tongue receptors and CN IX", "why": "These do not initiate the angular VOR."}, {"text": "Semicircular canals and vestibular division of CN VIII", "why": "Angular head rotation changes vestibular afferent activity, initiating compensatory eye movements."}], "answer": 4}, {"id": "Q204", "deck": "reflex", "ref": "slide-reflex-10", "page": 10, "topic": "Vestibulo-ocular reflex", "stem": "A healthy person turns the head to the right while maintaining fixation on a stationary target. Which horizontal eye muscles contract to generate the compensatory leftward slow eye movement?", "options": [{"text": "Both levator muscles alone", "why": "Eyelid elevation does not generate compensatory horizontal gaze."}, {"text": "Both medial recti", "why": "This produces convergence rather than conjugate leftward movement."}, {"text": "Right lateral rectus and left medial rectus", "why": "These turn eyes right, in the same direction as the head rather than the compensatory direction."}, {"text": "Both lateral recti", "why": "This would diverge the eyes rather than produce conjugate left gaze."}, {"text": "Left lateral rectus and right medial rectus", "why": "Eyes move opposite the head: left eye abducts via VI, and right eye adducts via III through internuclear connections."}], "answer": 4}, {"id": "Q205", "deck": "reflex", "ref": "slide-reflex-10", "page": 10, "topic": "Vestibulo-ocular reflex", "stem": "Which central pathway coordinates horizontal VOR output to the two eyes?", "options": [{"text": "LGN directly to both facial nerves", "why": "This is not the vestibular conjugate gaze pathway."}, {"text": "Vestibular nuclei to abducens nucleus, with internuclear neurons via MLF to contralateral oculomotor nucleus", "why": "The VI motor component drives ipsilateral lateral rectus while crossed internuclear input drives the other eye's medial rectus."}, {"text": "Pretectal nuclei to superior cervical ganglia only", "why": "This does not coordinate VI/III horizontal eye movements."}, {"text": "Visual cortex directly to lens zonules", "why": "Zonules are mechanical suspensory fibers, not neuronal effectors for eye rotation."}, {"text": "Spinal trigeminal nucleus directly to both ciliary muscles", "why": "This confuses corneal afference with gaze output."}], "answer": 1}, {"id": "Q206", "deck": "reflex", "ref": "slide-reflex-10", "page": 10, "topic": "Vestibulo-ocular reflex", "stem": "What is the principal functional purpose of the VOR?", "options": [{"text": "Increasing lens opacity in bright light", "why": "Lens opacity is pathological and not a VOR function."}, {"text": "Stabilizing the retinal image during head motion", "why": "Compensatory eye movement limits retinal image slip and can operate without conscious visual processing, including in darkness."}, {"text": "Generating a permanent physiological blind spot", "why": "The blind spot comes from the optic disc."}, {"text": "Closing both eyelids whenever an object is near", "why": "That is not the purpose of vestibular gaze stabilization."}, {"text": "Replacing all pupillary light responses", "why": "VOR governs gaze, while the light reflex governs pupil size."}], "answer": 1}, {"id": "Q207", "deck": "reflex", "ref": "slide-reflex-10", "page": 10, "topic": "Vestibulo-ocular reflex", "stem": "A lesion destroys the left abducens nucleus rather than only the left abducens nerve. Which deficit is expected during attempted left gaze?", "options": [{"text": "Both eyes fail to make normal conjugate leftward movement", "why": "The nucleus contains left lateral rectus motor neurons and internuclear neurons for right medial rectus via the MLF; a nerve lesion alone mainly impairs left abduction."}, {"text": "Both eyes lose right visual fields", "why": "This is a left postchiasmal visual pathway pattern."}, {"text": "Only the left pupil fails to constrict", "why": "VI is not the pupil efferent nerve."}, {"text": "Both medial recti are paralyzed during near convergence as an obligatory result", "why": "The medial rectus final motor neurons are in III, and convergence may remain available."}, {"text": "Only left corneal sensation is lost", "why": "Corneal afference is V1."}], "answer": 0}, {"id": "Q208", "deck": "reflex", "ref": "slide-reflex-11", "page": 11, "topic": "Oculocephalic testing", "stem": "An unconscious patient has no suspected cervical spine injury. When the head is gently rotated right, the eyes move left within the orbits. What does this demonstrate?", "options": [{"text": "A normal patient must keep the eyes centered in the orbits during this test", "why": "That would move gaze with the head rather than compensate."}, {"text": "A right optic nerve afferent defect", "why": "Optic nerve input is not the initiating afferent limb."}, {"text": "Isolated sympathetic denervation", "why": "Horner syndrome does not define this gaze reflex pattern."}, {"text": "Necessarily absent brainstem function", "why": "The described movement supports functioning reflex circuitry."}, {"text": "An intact oculocephalic reflex through vestibular–brainstem–ocular motor pathways", "why": "Compensatory movement opposite head rotation is the expected doll's-eye response in this context."}], "answer": 4}, {"id": "Q209", "deck": "reflex", "ref": "slide-reflex-11", "page": 11, "topic": "Oculocephalic testing", "stem": "During oculocephalic testing in an unconscious patient, both eyes remain fixed in the orbits and move with the head. Which interpretation is best?", "options": [{"text": "This proves isolated macular degeneration", "why": "Retinal central acuity loss does not explain the entire absent compensatory movement."}, {"text": "This is the normal intact doll's-eye response", "why": "An intact response moves eyes opposite to the head within the orbits."}, {"text": "This is simply normal near convergence", "why": "The stimulus is head rotation, not a near target."}, {"text": "This proves bilateral first-pouch malformation", "why": "Pouch derivatives do not localize this bedside response."}, {"text": "The compensatory VOR is absent or impaired, requiring interpretation in the clinical context", "why": "This can reflect dysfunction along vestibular/brainstem/ocular motor pathways; drugs and other confounders matter, so the maneuver alone does not establish brain death."}], "answer": 4}, {"id": "Q210", "deck": "reflex", "ref": "slide-reflex-11", "page": 11, "topic": "Oculocephalic testing", "stem": "A comatose trauma patient has possible unstable cervical injury. Which action is appropriate regarding the doll's-eye maneuver?", "options": [{"text": "Use neck rotation to rule out vertebral fracture", "why": "The maneuver cannot safely establish fracture absence."}, {"text": "Rotate the head forcefully to maximize the response", "why": "This risks worsening a potential cervical injury."}, {"text": "Perform the maneuver only toward the painful side", "why": "Side choice does not remove the instability risk."}, {"text": "Avoid rotating the head for this maneuver until cervical safety is established", "why": "The source specifically cautions against oculocephalic testing when cervical instability is suspected."}, {"text": "Interpret pupils alone as proof the neck is stable", "why": "Pupil examination does not determine cervical structural stability."}], "answer": 3}, {"id": "Q211", "deck": "reflex", "ref": "slide-reflex-12", "page": 12, "topic": "MLF anatomy", "stem": "Where is the medial longitudinal fasciculus located?", "options": [{"text": "Within the thyroid migration tract", "why": "Thyroglossal duct is unrelated to ocular internuclear coordination."}, {"text": "Within the lens capsule", "why": "This is an optical structure rather than a central white matter tract."}, {"text": "Near the midline in brainstem tegmentum, extending from upper medulla through pons to midbrain", "why": "The paired tract links vestibular and ocular motor nuclei and coordinates conjugate movement."}, {"text": "Along the lateral surface of the temporal optic radiation only", "why": "MLF is a brainstem tract, not Meyer's loop."}, {"text": "In the external acoustic canal", "why": "This is not CNS white matter."}], "answer": 2}, {"id": "Q212", "deck": "reflex", "ref": "slide-reflex-12", "page": 12, "topic": "MLF anatomy", "stem": "Which nuclei are linked by the MLF to coordinate eye movements?", "options": [{"text": "Only facial and hypoglossal nuclei", "why": "These do not define the MLF ocular coordination system."}, {"text": "Only olfactory bulbs", "why": "These are forebrain sensory structures unrelated to the MLF gaze system."}, {"text": "Only ciliary and superior cervical ganglia", "why": "These are peripheral autonomic ganglia rather than MLF-linked brainstem nuclei."}, {"text": "Vestibular and ocular motor nuclei III, IV, and VI", "why": "These connections support conjugate movements and vestibulo-ocular responses; the horizontal exam most often highlights VI-to-III communication."}, {"text": "Only lateral and medial geniculate nuclei", "why": "These are thalamic sensory relays, not the principal MLF partners."}], "answer": 3}, {"id": "Q213", "deck": "reflex", "ref": "slide-reflex-13", "page": 13, "topic": "Internuclear ophthalmoplegia", "stem": "On rightward gaze, the left eye fails to adduct and the right eye has abducting nystagmus. Convergence is preserved. Which structure is most likely injured?", "options": [{"text": "Right optic nerve", "why": "This would affect visual afference rather than coordinated eye movement."}, {"text": "Right MLF", "why": "This would cause right adduction weakness on leftward gaze."}, {"text": "Left MLF", "why": "INO is named for the side of the impaired adducting eye; intact convergence helps show that medial rectus can still function through near pathways."}, {"text": "Left abducens nerve", "why": "This would impair left abduction, not left adduction."}, {"text": "Left facial nerve", "why": "This would affect eyelid/facial movement rather than medial rectus coordination."}], "answer": 2}, {"id": "Q214", "deck": "reflex", "ref": "slide-reflex-13", "page": 13, "topic": "Internuclear ophthalmoplegia", "stem": "Which sign is characteristic of the eye opposite an MLF lesion during attempted lateral gaze away from the lesion?", "options": [{"text": "Abducting nystagmus", "why": "The contralateral eye abducts with nystagmus while the ipsilateral eye has impaired adduction."}, {"text": "Loss of all corneal sensation", "why": "Corneal sensation uses V1 and is not a defining INO sign."}, {"text": "Permanent eyelid closure", "why": "This is not the characteristic contralateral ocular finding."}, {"text": "Fixed pupil dilation in every case", "why": "Pupillary dysfunction is not required for isolated INO."}, {"text": "Complete inability to abduct in every case", "why": "The contralateral eye usually abducts, often with nystagmus."}], "answer": 0}, {"id": "Q215", "deck": "reflex", "ref": "slide-reflex-13", "page": 13, "topic": "Internuclear ophthalmoplegia", "stem": "A 29-year-old patient with prior episodes of limb numbness develops horizontal diplopia. During leftward gaze, the right eye adducts slowly and incompletely while the left eye abducts with nystagmus. Both eyes converge when a target is brought toward the nose, and pupil responses are normal. MRI identifies a small paramedian brainstem demyelinating lesion. Which location best accounts for this examination?", "options": [{"text": "Left optic tract", "why": "This would produce right homonymous visual loss rather than the described gaze deficit."}, {"text": "Left MLF", "why": "This would weaken left adduction during rightward gaze."}, {"text": "Right CN VI nerve", "why": "This would cause right abduction weakness rather than impaired right adduction."}, {"text": "Complete right CN III nerve", "why": "This usually affects more III functions; preserved convergence and the internuclear pattern favor MLF injury."}, {"text": "Right MLF", "why": "The impaired adducting eye identifies the side of INO. Multiple sclerosis is a classic association in younger patients, and convergence can be preserved."}], "answer": 4}, {"id": "Q216", "deck": "reflex", "ref": "slide-reflex-13", "page": 13, "topic": "Internuclear ophthalmoplegia", "stem": "An older patient develops sudden unilateral INO with a small brainstem infarct. Which association best matches the age and onset?", "options": [{"text": "Isolated first-cleft persistence", "why": "This causes ear/neck anomalies, not an acute MLF syndrome."}, {"text": "A new absence of the optic disc", "why": "This does not describe an acute brainstem internuclear lesion."}, {"text": "Caudal neuropore closure failure at age 70", "why": "Neural tube closure is an embryonic event."}, {"text": "Brainstem ischemic stroke", "why": "Stroke is a classic INO cause in older adults; multiple sclerosis is a common association in younger patients, especially with bilateral involvement."}, {"text": "An obligatory inherited TCOF1 mutation", "why": "TCOF1 causes congenital mandibulofacial dysostosis rather than an acute gaze deficit."}], "answer": 3}, {"id": "Q217", "deck": "reflex", "ref": "slide-reflex-13", "page": 13, "topic": "Internuclear ophthalmoplegia", "stem": "Why does preserved convergence support INO over a complete medial rectus/III motor lesion?", "options": [{"text": "Convergence depends exclusively on CN VI", "why": "Medial rectus convergence uses III, not VI."}, {"text": "It proves the MLF cannot be injured", "why": "Preserved convergence is compatible with MLF injury."}, {"text": "Convergence requires no muscle contraction", "why": "Both medial recti must contract."}, {"text": "It proves the optic nerve is completely severed", "why": "The finding does not imply absent visual afference."}, {"text": "It shows medial rectus can contract when activated through near-response pathways", "why": "An internuclear connection can be impaired while the final motor apparatus remains functional; convergence preservation is common but not universal in INO."}], "answer": 4}, {"id": "Q218", "deck": "reflex", "ref": "slide-reflex-13", "page": 13, "topic": "Internuclear ophthalmoplegia", "stem": "A paramedian pontine lesion affects the left horizontal gaze center/abducens nuclear region and the adjacent left MLF. Neither eye moves left; on attempted right gaze, only the right eye abducts. Which syndrome best describes this extension of INO?", "options": [{"text": "Isolated left optic neuritis", "why": "This affects sensory vision, not this combined horizontal motor pattern."}, {"text": "Bitemporal hemianopia", "why": "This is a chiasmal visual field pattern."}, {"text": "Isolated right VI nerve palsy", "why": "That would impair right abduction, the movement preserved here."}, {"text": "Isolated Adie tonic pupil", "why": "This is pupillary parasympathetic dysfunction rather than a conjugate gaze syndrome."}, {"text": "Left one-and-a-half syndrome", "why": "Ipsilateral gaze palsy plus ipsilateral INO leaves only contralateral abduction as the remaining horizontal movement."}], "answer": 4}, {"id": "Q219", "deck": "reflex", "ref": "slide-reflex-14", "page": 14, "topic": "Integrated reflex review", "stem": "A patient has normal pupillary constriction to light, bilateral corneal blinking, and compensatory eye movement with head rotation. Which mapping correctly describes the three afferent nerves in that order?", "options": [{"text": "IX, X, XI", "why": "These do not carry the three tested sensory inputs."}, {"text": "III, VII, VI", "why": "These are major efferent nerves for the corresponding responses, not the afferent triad."}, {"text": "II, V1, VIII", "why": "Light uses optic afference, corneal touch uses ophthalmic trigeminal afference, and rotation uses vestibular afference."}, {"text": "V1, II, IX", "why": "This swaps visual and corneal inputs and misassigns vestibular input."}, {"text": "VII, III, XII", "why": "These are motor nerves and do not match the sensory stimuli."}], "answer": 2}, {"id": "Q220", "deck": "reflex", "ref": "slide-reflex-14", "page": 14, "topic": "Integrated reflex review", "stem": "Which lesion can impair horizontal conjugate gaze while leaving visual fields, corneal sensation, and pupillary light responses intact?", "options": [{"text": "Complete optic nerve transection", "why": "This produces monocular afferent visual loss and a light-input abnormality."}, {"text": "Complete III lesion including parasympathetics", "why": "This directly impairs ocular output and pupil constriction."}, {"text": "An isolated MLF lesion", "why": "MLF coordinates ocular motor nuclei; it can produce INO without directly damaging retinal visual, V1 sensory, or pupil light-reflex pathways."}, {"text": "Complete V1 lesion", "why": "This impairs corneal sensation and afferent blink responses."}, {"text": "Central optic chiasm destruction", "why": "This produces heteronymous visual field loss."}], "answer": 2}]};
